:{"flag":"nadja-rencontree"}}],"boutique":[],"etape_seulement":false,"auberge":false},{"id":"qarzim-residence","nom":"Résidence d'Aubeclaire","description":"La maison des ambassadeurs d'Aubeclaire : jardin à l'ombre des palmiers, drapeaux bleus et blancs.","decor":"qarzim-residence","position":{"x":880,"y":450},"ville":"qarzim","position_plan":{"x":240,"y":220},"disponible_si":{"flag":"sables-ouverts"},"pnj":[{"id":"seraphine","si":{"flag":"seraphine-recrutee"}},{"id":"aveline","si":{"flag":"aveline-rencontree"}}],"boutique":[],"etape_seulement":false,"auberge":false},{"id":"route-des-caravanes","nom":"Route des Caravanes","description":"La piste qui relie Aubeclaire à Qarzim, entre les dunes et les rochers.","decor":"route-des-caravanes","position":{"x":1260,"y":230},"disponible_si":{"flag":"ch2-depart-fait"},"pnj":[],"boutique":[],"etape_seulement":false,"auberge":false},{"id":"campement-lunecroc","nom":"Campement Lunecroc","description":"Les tentes de la tribu de Kaya, au pied d'une falaise rouge. Les feux y brûlent toute la nuit.","decor":"campement-lunecroc","position":{"x":430,"y":760},"disponible_si":{"flag":"sables-ouverts"},"pnj":[{"id":"sorha"},{"id":"kaya","si":{"flag":"kaya-recrutee"}}],"boutique":[],"etape_seulement":false,"auberge":false},{"id":"mines-ether","nom":"Mines d'éther","description":"Des puits creusés dans la roche violette, gardés par les mercenaires de la Concorde.","decor":"mines-ether","position":{"x":1500,"y":700},"disponible_si":{"flag":"sables-ouverts"},"pnj":[],"boutique":[],"etape_seulement":false,"auberge":false},{"id":"canyon-des-chacals","nom":"Canyon des Chacals","description":"Un canyon étroit aux parois rouges, où résonnent les jappements.","decor":"canyon-des-chacals","position":{"x":1320,"y":880},"disponible_si":{"flag":"sables-ouverts"},"pnj":[],"boutique":[],"etape_seulement":false,"auberge":false},{"id":"ruines-de-sel","nom":"Ruines de Sel","description":"Une cité engloutie par le sel : des colonnes blanches qui sortent des dunes comme des os.","decor":"ruines-de-sel","position":{"x":700,"y":910},"disponible_si":{"quete_etape":{"q-ch2-routes":"tempete"}},"pnj":[],"boutique":[],"etape_seulement":false,"auberge":false},{"id":"oasis-perdue","nom":"Oasis perdue","description":"Trois palmiers morts et un bassin vide, au milieu de nulle part.","decor":"oasis-perdue","position":{"x":300,"y":320},"pnj":[],"boutique":[],"etape_seulement":true,"auberge":false},{"id":"dunes-chantantes","nom":"Dunes chantantes","description":"Des dunes qui chantent quand le vent souffle, comme un chœur lointain.","decor":"dunes-chantantes","position":{"x":1650,"y":380},"pnj":[],"boutique":[],"etape_seulement":true,"auberge":false},{"id":"puits-asseches","nom":"Puits asséchés","description":"Une ligne de puits à sec, le long d'un ancien canal.","decor":"puits-asseches","position":{"x":1120,"y":980},"pnj":[],"boutique":[],"etape_seulement":true,"auberge":false},{"id":"repaire-pillards","nom":"Repaire des pillards","description":"Des tentes rapiécées cachées entre deux rochers en forme de crocs.","decor":"repaire-pillards","position":{"x":1700,"y":600},"pnj":[],"boutique":[],"etape_seulement":true,"auberge":false},{"id":"toits-de-qarzim","nom":"Toits de Qarzim","description":"Un dédale de terrasses, de cordes à linge et de coupoles.","decor":"toits-de-qarzim","position":{"x":940,"y":470},"ville":"qarzim","position_plan":{"x":820,"y":230},"pnj":[],"boutique":[],"etape_seulement":true,"auberge":false}]}},"pnj":{"ouzram":{"id":"ouzram","nom":"Maître Ouzram Telli","titre":"Armurier du Grand Bazar","description":"Vieil homme sec au turban safran, lunettes d'or, mains couvertes de petites brûlures de forge.","accueil":"Entrez, entrez ! Une lame de Qarzim ne rouille jamais, et mes prix ne mentent qu'à moitié."},"ziyane":{"id":"ziyane","nom":"Mère Ziyane","titre":"Aubergiste de l'Oasis Bleue","description":"Femme ronde au rire sonore, foulard indigo, bracelets qui tintent à chaque geste.","accueil":"De l'eau fraîche, un lit sous les voiles, et pas de questions. Bienvenue à l'Oasis Bleue."},"ibrek":{"id":"ibrek","nom":"Ibrek Sall","titre":"Intendant de la Guilde à Qarzim","description":"Jeune vulpin aux oreilles rousses, lunettes rondes, registre toujours ouvert. Il connaît les tarifs de tous les contrats par cœur.","accueil":"Comptoir de la Rose des Vents ! Les contrats sont au tableau ; le matériel, c'est ici."},"hassad":{"id":"hassad","nom":"Prévôt Hassad Meriyem","titre":"Prévôt de la Concorde","description":"Homme mince en soie blanche, barbe taillée au cordeau, une bague-cristal violette à chaque main. Courtois, glacial."},"vashti":{"id":"vashti","nom":"Conseillère Vashti Orren","titre":"Conseillère de la Concorde","description":"Femme élégante aux yeux maquillés de khôl, toujours un éventail à la main. Elle sourit trop."},"sorha":{"id":"sorha","nom":"L'Ancienne Sorha","titre":"Doyenne de la tribu Lunecroc","description":"Vieille ourvalis aux oreilles grises, aveugle d'un œil, appuyée sur un bâton gravé de loups. La grand-mère de Kaya."},"tavek":{"id":"tavek","nom":"Tavek Lunecroc","titre":"Chef de guerre lunecroc","description":"Grand ourvalis aux oreilles noires, peintures de guerre rouges, griffes de fer aux poings. Le cousin de Kaya."},"kezir":{"id":"kezir","nom":"Kezir","titre":"Maître de la Main de Sable","description":"Silhouette voilée de noir, voix douce, yeux dorés. Personne n'a jamais vu son visage."},"vask":{"id":"vask","nom":"Capitaine Orlen Vask","titre":"Mercenaire de la Concorde","description":"Cuirasse dorée cabossée, crâne rasé, cicatrice du menton à l'oreille."},"faelis":{"id":"faelis","nom":"Faelis Brumevent","titre":"Marchande elfe","description":"Elfe sylvaine aux cheveux d'argent tressés de feuilles, longue cape vert sombre. Elle vend des herbes, et des secrets."},"archiviste":{"id":"archiviste","nom":"Maître Corvin","titre":"Archiviste royal","description":"Petit homme voûté aux doigts tachés d'encre, qui parle aux livres plus qu'aux gens."},"aureliath":{"id":"aureliath","nom":"Grand Prieur Auréliath","titre":"Ordre de la Lumière Sereine","description":"Crâne rasé, barbe blanche, sourire bienveillant un peu trop parfait."},"rowena":{"id":"rowena","nom":"Dame Rowena","titre":"Maîtresse de la Guilde","description":"Cheveux gris coupés court, cicatrice sur l'œil, pipe éteinte entre les dents."},"edmund-iv":{"id":"edmund-iv","nom":"Edmund IV","titre":"Roi d'Aubeclaire","description":"Couronne lourde, barbe grise, regard fatigué et dur."},"seraphine":{"id":"seraphine","nom":"Séraphine d'Aubeclaire","titre":"Princesse","description":"Longs cheveux blond pâle, petit diadème, robe blanche et or. Seconde de la lignée, espiègle sous l'étiquette."},"elianne":{"id":"elianne","nom":"Sœur Elianne","titre":"Prêtresse","description":"Cheveux noirs au carré sous un voile clair, chapelet de perles bleues. Douce, patiente, têtue quand il s'agit de justice.","accueil":"Que la Lumière vous garde. Le Temple vend peu de choses, mais elles soignent."},"kaya":{"id":"kaya","nom":"Kaya Lunecroc","titre":"Aventurière ourvalis, rang E","description":"Oreilles et queue de loup argentées, bandeau rouge, épée à la hanche. Franche jusqu'à la gaffe."},"vorthak":{"id":"vorthak","nom":"Vorthak","titre":"Émissaire des Cendres","description":"Démon en armure noire aux flammes violettes."},"ferrand":{"id":"ferrand","nom":"Ferrand","titre":"Marchand de reliques","description":"Moustache noire, bagues à tous les doigts, sourire huileux, manteau violet et or trop beau pour son commerce.","accueil":"Un objet dont vous ignorez tout ? Dix pièces, et je vous dis ce qu'il vaut vraiment.","identifie":10},"halvine":{"id":"halvine","nom":"Dame Halvine Corbelet","titre":"Marchande du Comptoir","description":"Petite femme vive aux lunettes rondes, tablier plein de poches, boulier à la main, compte plus vite que lui.","accueil":"Bienvenue au Comptoir ! Regardez tout, touchez peu, et payez comptant."},"bram":{"id":"bram","nom":"Bram","titre":"Tavernier du Chaudron Fêlé","description":"Colosse jovial au crâne lisse et à la grande barbe brune, tablier taché, chope à la main, cœur d'or.","accueil":"Installez-vous ! Ici on mange chaud, et le lit est à l'étage."},"intendant-guilde":{"id":"intendant-guilde","nom":"Maître Barnoul Kestrin","titre":"Intendant de la Guilde","description":"Costaud, peau mate, barbe brune, tablier de cuir, un registre à la main, l'air sévère. Rien ne sort de la réserve sans sa signature.","accueil":"Nom, rang, et ce qu'il vous faut. Tout est noté dans le registre."},"lina":{"id":"lina","nom":"Lina","titre":"Jeune tanneuse","description":"Disparue du quartier des Tanneurs."},"tobin":{"id":"tobin","nom":"Tobin","titre":"Apprenti de l'Ordre","description":"Dix-neuf ans, cheveux roux en bataille, taches de rousseur, un livre toujours sous le bras. Curieux, trop curieux."},"gareth":{"id":"gareth","nom":"Gareth","titre":"Fermier de la Combe-aux-Saules","description":"Mains calleuses, chapeau de paille, salopette bleue et fourche à la main."},"mentor":{"id":"mentor","nom":"Maître Orlo","titre":"Mentor d'enfance","description":"Vieux bibliothécaire bourru."},"rival":{"id":"rival","nom":"Cassian","titre":"Rival d'enfance","description":"Fils de garde, fier et rapide."},"ami-enfance":{"id":"ami-enfance","nom":"Pipa","titre":"Amie d'enfance","description":"Rieuse, intrépide, toujours une égratignure au genou."}},"scenes":{"av-ronde":{"id":"av-ronde","titre":"Aveline — La ronde de nuit","type":"individuel","lieu":"lysmont-place","decor":"lysmont-place","debut":"debut","disponible_si":{"flag":"examen-reussi"},"repetable":false,"romance":false,"pnj":"aveline","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Vous croisez Aveline pendant sa ronde, une lanterne à la main. « Encore debout ? Les héros ne dorment jamais, c'est ça ? »"}],"effets":[],"choix":[{"texte":"« Je pourrais vous accompagner. Deux paires d'yeux valent mieux qu'une. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":5}}],"aller":"accompagne"},{"texte":"« Et vous, capitaine ? Vous ne dormez jamais non plus. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":3}}],"aller":"question"},{"texte":"« Ce n'est pas un peu ennuyeux, de tourner en rond toute la nuit ? »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":-2}}],"aller":"vexee"}],"fin":false},"accompagne":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Elle hésite, puis hoche la tête. Vous marchez longtemps en silence. C'est un silence étonnamment agréable."},{"qui":"aveline","expression":"joie","dit":"Au détour d'une rue, elle s'arrête net devant une pâtisserie fermée, le nez presque collé à la vitre. Puis elle se reprend. « Je… vérifiais les serrures. »"}],"effets":[{"flag":"heros:secret-patisserie"}],"choix":[],"suite":"fin","fin":false},"question":{"repliques":[{"qui":"aveline","expression":"tristesse","dit":"« Pas beaucoup, non. » Elle regarde vers le nord. « Quand je ferme les yeux, je vois Valgrane. » Elle n'en dit pas plus."}],"effets":[],"choix":[],"suite":"fin","fin":false},"vexee":{"repliques":[{"qui":"aveline","expression":"colere","dit":"« C'est ce qui permet à la ville de dormir tranquille. » Elle s'éloigne d'un pas raide."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"av-entrainement":{"id":"av-entrainement","titre":"Aveline — Leçon d'escrime","type":"individuel","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"flag":"examen-reussi","affinite_min":{"aveline":10}},"repetable":false,"romance":false,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Dans la cour du château, Aveline vous lance une épée de bois. « Votre garde est catastrophique. Montrez-moi ce que vous savez faire. »"}],"effets":[],"choix":[{"texte":"Vous battre sérieusement. (Force, difficulté 16)","visible_si_bloque":false,"test":{"carac":"FOR","difficulte":16,"reussite":"gagne","echec":"perd"},"effets":[]},{"texte":"Esquiver et la faire tourner en bourrique. (Agilité, difficulté 16)","visible_si_bloque":false,"test":{"carac":"AGI","difficulte":16,"reussite":"gagne","echec":"perd"},"effets":[]},{"texte":"Tricher : lui jeter du sable aux yeux.","visible_si_bloque":false,"effets":[{"affinite":{"aveline":-6}}],"aller":"triche"}],"fin":false},"gagne":{"repliques":[{"qui":"aveline","expression":"surprise","dit":"Votre lame de bois s'arrête à un doigt de sa gorge. Elle vous fixe, sidérée… puis éclate de rire. Un vrai rire."},{"qui":"aveline","expression":"joie","dit":"« Encore. Demain. Même heure. » Ce n'est pas une question."}],"effets":[{"affinite":{"aveline":7},"xp":40}],"choix":[],"suite":"fin","fin":false},"perd":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Vous voilà sur le dos, sa lame de bois sur votre poitrine. « Pas mal. Pour un débutant. » Elle vous tend la main pour vous relever."}],"effets":[{"affinite":{"aveline":4},"xp":25}],"choix":[],"suite":"fin","fin":false},"triche":{"repliques":[{"qui":"aveline","expression":"colere","dit":"Elle crache le sable, furieuse. « Sur un champ de bataille, peut-être. Ici, c'est une leçon d'honneur. Recommencez quand vous en aurez. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"av-confidence":{"id":"av-confidence","titre":"Aveline — Ce qu'on ne dit à personne","type":"individuel","lieu":"taverne","decor":"taverne","debut":"debut","disponible_si":{"affinite_palier":{"aveline":"proche"}},"repetable":false,"romance":false,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Aveline vous attend au fond de la taverne, devant deux chopes qu'elle n'a pas touchées. « Asseyez-vous. J'ai… quelque chose à vous dire. »"},{"qui":"aveline","expression":"tristesse","dit":"« Mon père, Gauvain de Castelroc, commandait Valgrane. On l'a accusé d'avoir ouvert les portes aux Cendres. On l'a exécuté sans procès. »"},{"qui":"aveline","expression":"neutre","dit":"« Je n'ai jamais cru à sa trahison. Mais les archives militaires de Valgrane ont été scellées… par l'Ordre. Pourquoi l'Ordre ? »"}],"effets":[],"choix":[{"texte":"« Je vous aiderai à découvrir la vérité. Je vous en fais la promesse. »","visible_si_bloque":false,"effets":[{"flag":"heros:promesse-aveline","affinite":{"aveline":8},"quete":{"id":"q-aveline","etape":"archives"}}],"aller":"promesse"},{"texte":"« Et si la vérité ne vous plaisait pas ? »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":3},"quete":{"id":"q-aveline","etape":"archives"}}],"aller":"prudent"}],"fin":false},"promesse":{"repliques":[{"qui":"aveline","expression":"gene","dit":"Elle vous regarde longtemps. Puis, très doucement, elle pose sa main sur la vôtre. « Merci. » Elle la retire aussitôt, écarlate."}],"effets":[],"choix":[],"suite":"fin","fin":false},"prudent":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"« Alors au moins, je saurai. » Elle lève sa chope. « À la vérité, quelle qu'elle soit. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"(Quête de compagnon « Le Serment brisé » : la suite au chapitre 2.)"}],"effets":[],"choix":[],"fin":true}}},"av-remparts":{"id":"av-remparts","titre":"Aveline — Les remparts au crépuscule","type":"individuel","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"affinite_palier":{"aveline":"amoureuse"}},"repetable":false,"romance":true,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Le soleil se couche sur Lysmont. Aveline est assise sur le parapet, les jambes dans le vide, sans armure."},{"qui":"aveline","expression":"gene","dit":"« Je ne suis pas douée pour… ça. Les mots. » Elle fixe l'horizon. « Avec une épée, je sais toujours quoi faire. Avec vous, jamais. »"}],"effets":[],"choix":[{"texte":"Vous asseoir à côté d'elle et prendre sa main.","visible_si_bloque":false,"effets":[{"affinite":{"aveline":5}}],"aller":"main"},{"texte":"« Alors ne dites rien. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":5}}],"aller":"main"}],"fin":false},"main":{"repliques":[{"qui":"aveline","expression":"joie","dit":"Elle rit doucement, nerveusement, et pose la tête sur votre épaule. Le soleil disparaît derrière les tours blanches…"},{"qui":"narrateur","expression":"neutre","dit":"(Fondu au noir.)"}],"effets":[],"choix":[],"fin":true}}},"ch1-appel":{"id":"ch1-appel","titre":"L'Appel","type":"groupe","lieu":"temple-du-seuil","decor":"temple-du-seuil","debut":"debut","disponible_si":{"pas_flag":"appel-fait"},"repetable":false,"romance":false,"quete":"q-ch1-appel","pnj":"aureliath","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Printemps 1012. Un cercle de lumière bleue embrase le sol du Temple du Seuil. Des chants montent, des vitraux vibrent… puis le silence."},{"qui":"narrateur","expression":"neutre","dit":"Au centre du cercle, des silhouettes se relèvent, hagardes : les invoqués. À la lisière de la lumière, d'autres jeunes gens, attirés ici par une résonance qu'ils ne savent pas nommer : les réincarnés.","si":{"origine":"reincarne"}},{"qui":"aureliath","expression":"neutre","dit":"« Bienvenue à Velmaris, [[Appelé||Appelés]]. Je suis Auréliath, Grand Prieur de l'Ordre de la Lumière Sereine. [[N'aie||N'ayez]] crainte : la Lumière [[t'a choisi||vous a choisis]]. »"},{"qui":"aureliath","expression":"neutre","dit":"« Le Souverain des Cendres s'est éveillé au nord. Le Mur d'Aube faiblit. Le royaume a besoin de héros. »"},{"qui":"aveline","expression":"neutre","dit":"Une jeune femme en armure argentée s'avance, la main sur le pommeau. « Capitaine Aveline de Castelroc. Je suis chargée de [[ta||votre]] sécurité. » Son regard s'attarde sur [[toi||vous]], méfiant."}],"effets":[],"choix":[{"texte":"« Un monde de magie ? Génial. Où est-ce qu'on signe ? » (enthousiaste)","visible_si_bloque":false,"effets":[{"reputation":{"ordre":5},"affinite":{"aveline":2}}],"aller":"enthousiaste"},{"texte":"« Personne ne [[m'a demandé mon||nous a demandé notre]] avis. Qui a décidé de [[m'arracher à ma vie||nous arracher à nos vies]] ? » (méfiant)","visible_si_bloque":false,"effets":[{"flag":"mefiance-ordre","reputation":{"ordre":-5},"affinite":{"aveline":4}}],"aller":"mefiant"},{"texte":"« Excusez-moi, il y a des toilettes dans ce monde ? » (humour)","visible_si_bloque":false,"effets":[{"affinite":{"aveline":3}}],"aller":"humour"}],"fin":false},"enthousiaste":{"repliques":[{"qui":"aureliath","expression":"neutre","dit":"Le Grand Prieur sourit largement. « Voilà l'esprit des héros ! »"},{"qui":"aveline","expression":"neutre","dit":"Aveline soupire. « Les derniers à avoir dit ça sont enterrés sous le Mur d'Aube. »"}],"effets":[],"choix":[],"suite":"question","fin":false},"mefiant":{"repliques":[{"qui":"aureliath","expression":"neutre","dit":"Le sourire du Grand Prieur se fige une fraction de seconde. « La Lumière a ses raisons. [[Tu les comprendras||Vous les comprendrez]]. »"},{"qui":"aveline","expression":"neutre","dit":"Aveline [[te||vous]] jette un regard nouveau. Presque… approbateur."}],"effets":[],"choix":[],"suite":"question","fin":false},"humour":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un acolyte s'étrangle. Auréliath cligne des yeux."},{"qui":"aveline","expression":"joie","dit":"Aveline détourne la tête, mais [[tu l'as||vous l'avez]] vue : elle a souri. « Par ici. Et oui, il y en a. »"}],"effets":[],"choix":[],"suite":"question","fin":false},"question":{"parole_a":{"regle":{"classe":["arcaniste","invocateur","guerisseur","barde","alchimiste"]},"question":{"qui":"aureliath","expression":"neutre","dit":"« {pseudo}. Je sens quelque chose s'éveiller en toi. Dis-moi : que sais-tu de la magie de ce monde ? »"},"reponses":[{"texte":"« Je la sens crépiter au bout de mes doigts. Le feu, le givre… ils me répondent déjà. »","si":{"classe":"arcaniste"},"effets":[{"reputation":{"ordre":3}}],"aller":"suite"},{"texte":"« Quelque chose m'accompagne depuis mon arrivée. Une présence, à mes côtés. »","si":{"classe":"invocateur"},"effets":[{"reputation":{"ordre":2}}],"aller":"suite"},{"texte":"« Je sais seulement que mes mains apaisent la douleur. Le reste, je l'apprendrai. »","si":{"classe":"guerisseur"},"effets":[{"reputation":{"ordre":4}}],"aller":"suite"},{"texte":"« La magie ? Chez moi, ça s'appelle une bonne chanson au bon moment. »","si":{"classe":"barde"},"effets":[{"affinite":{"aveline":1}}],"aller":"suite"},{"texte":"« De la magie ? Montrez-moi vos fioles, je vous dirai ce que j'en pense. »","si":{"classe":"alchimiste"},"effets":[{"reputation":{"ordre":1}}],"aller":"suite"},{"texte":"« Je préfère l'acier. La magie, je la laisse à ceux qui ont le temps de réciter. »","si":{"classe":["lame-runique","gardien","berserker","ombre","archer"]},"effets":[{"affinite":{"aveline":2}}],"aller":"suite"},{"texte":"« Les anciens parlent du Voile et de ses dangers. Je sais qu'on ne joue pas avec. »","si":{"race":["elfe","demi-elfe"]},"effets":[{"flag":"mefiance-ordre"}],"aller":"suite"},{"texte":"« Rien du tout. Mais j'apprends vite. »","effets":[{"reputation":{"ordre":1}}],"aller":"suite"},{"texte":"« Assez pour me méfier de ceux qui s'en servent sur les autres sans demander. »","effets":[{"reputation":{"ordre":-3},"affinite":{"aveline":2}}],"aller":"suite"},{"texte":"« Ça dépend. Elle fait aussi le café ? »","effets":[{"affinite":{"aveline":1}}],"aller":"suite"}]},"repliques":[{"qui":"aureliath","expression":"neutre","dit":"Le Grand Prieur lève une main. Son regard [[te détaille longuement||parcourt vos visages un à un, puis s'arrête]]."}],"effets":[],"choix":[],"fin":false},"suite":{"repliques":[{"qui":"aureliath","expression":"neutre","dit":"« [[Repose-toi||Reposez-vous]]. Demain, la Couronne [[te||vous]] recevra. En attendant, la Guilde de la Rose des Vents [[t'ouvrira ses portes : tu y apprendras||vous ouvrira ses portes : vous y apprendrez]] à survivre. »"},{"qui":"narrateur","expression":"neutre","dit":"Ce soir-là, en contemplant les tours blanches de Lysmont depuis la fenêtre du temple, [[tu vois flotter devant tes yeux une fenêtre translucide : ton niveau, tes capacités… et ton don.||chacun de vous voit flotter devant ses yeux une fenêtre translucide : votre niveau, vos capacités… et votre don.]]"}],"effets":[{"flag":["appel-fait","aveline-rencontree"],"quete":{"id":"q-ch1-appel","etape":"examen"},"recruter":"aveline","journal":"L'Appel : {groupe} arrivent au Temple du Seuil. La capitaine Aveline de Castelroc est chargée de leur sécurité."}],"choix":[],"fin":true}}},"ch1-examen":{"id":"ch1-examen","titre":"L'examen de la Guilde","type":"groupe","lieu":"guilde","decor":"guilde","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"examen"}},"repetable":false,"romance":false,"quete":"q-ch1-appel","pnj":"rowena","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le hall de la Guilde de la Rose des Vents sent la bière, le cuir et la sueur. Des dizaines de regards se tournent vers vous."},{"qui":"rowena","expression":"neutre","dit":"« Ah. [[Un Appelé||Les Appelés]]. » Dame Rowena mâchonne sa pipe éteinte. « Ici, [[ton don ne vaut rien tant que tu n'as pas prouvé que tu sais||votre don ne vaut rien tant que vous n'avez pas prouvé que vous savez]] tenir debout. »"},{"qui":"kaya","expression":"neutre","dit":"Une jeune femme aux oreilles de loup argentées [[te||vous]] dévisage, adossée à un pilier. « Pff. [[Il a l'air tout mou||Ils ont l'air tout mous]]. Je parie dix pièces [[qu'il tombe||qu'ils tombent]] au premier coup. »"},{"qui":"kaya","expression":"neutre","dit":"Elle vous fixe un instant de plus, puis son regard s'adoucit. « …Un Ourvalis ? Hé. Bonne chance, alors. »","si":{"race":"ourvalis"}},{"qui":"rowena","expression":"neutre","dit":"« L'examen est simple : [[tu affrontes||vous affrontez]] notre golem d'entraînement. S'il [[te||vous]] met au tapis, [[reviens||revenez]] dans un an. »"}],"effets":[],"choix":[],"suite":"pari","fin":false},"pari":{"pari":{"mise":20,"gain":2,"flag":"pari-kaya","aller":"conseil","personne":"sans-pari"},"repliques":[{"qui":"kaya","expression":"neutre","dit":"Kaya fait sauter une pièce dans sa main. « Allez, soyons joueurs. Vingt pièces, pour [[toi||tout le groupe]], que [[tu ne tiens||vous ne tenez]] pas debout jusqu'au bout. [[Tu suis||Qui suit]] ? »"}],"effets":[],"choix":[],"fin":false},"sans-pari":{"repliques":[{"qui":"kaya","expression":"neutre","dit":"« Personne ne parie ? Tss. Prudent[[||s]], en plus d'être mou[[||s]]. » Elle range sa pièce, presque déçue."}],"effets":[],"choix":[],"suite":"conseil","fin":false},"conseil":{"parole_a":{"regle":{"classe":["lame-runique","gardien","berserker","ombre","archer"]},"question":{"qui":"rowena","expression":"neutre","dit":"Rowena pointe sa pipe vers {nom}. « Toi, {pseudo}. Ce golem fait deux fois ta taille. Tu comptes t'y prendre comment ? »"},"reponses":[{"texte":"« Je me mets devant et j'encaisse. [[Je frapperai quand il fatiguera.||Les autres frapperont pendant ce temps.]] »","si":{"classe":"gardien"},"effets":[{"reputation":{"guilde":3}}],"aller":"combat"},{"texte":"« Je cogne fort. Et s'il tient encore debout, je recommence. »","si":{"classe":["berserker","lame-runique"]},"effets":[{"reputation":{"guilde":2}}],"aller":"combat"},{"texte":"« Je cherche le point faible. Tout le monde en a un, même l'argile. »","si":{"classe":["ombre","archer"]},"effets":[{"reputation":{"guilde":3}}],"aller":"combat"},{"texte":"« De loin. Très loin. Avec quelque chose qui explose. »","si":{"classe":["arcaniste","invocateur","alchimiste"]},"effets":[{"reputation":{"guilde":2}}],"aller":"combat"},{"texte":"« Je tiens debout plus longtemps que lui.[[|| Et je garde les autres debout.]] »","si":{"classe":["guerisseur","barde"]},"effets":[{"reputation":{"guilde":2}}],"aller":"combat"},{"texte":"« Avec prudence. Je regarde d'abord comment il bouge. »","effets":[{"reputation":{"guilde":2}}],"aller":"combat"},{"texte":"« On verra bien une fois dedans. »","effets":[{"reputation":{"guilde":1}}],"aller":"combat"},{"texte":"« Vous n'auriez pas un golem plus petit ? »","effets":[{"reputation":{"guilde":1}}],"aller":"combat"}]},"repliques":[],"effets":[],"choix":[],"fin":false},"combat":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le golem d'argile se met en marche dans un grincement."}],"effets":[],"choix":[],"combat":{"rencontre":"examen-guilde","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Pas mal. Pas mal du tout. » Elle tamponne une carte de cuivre. « Rang F. Les contrats sont au tableau. Ne mourez pas bêtement. »"},{"qui":"kaya","expression":"neutre","dit":"Kaya rend la mise et y ajoute vingt pièces de sa poche, en grommelant. « Ouais, bon. [[Tu as||Vous avez]] de la chance. »","si":{"flag":"pari-kaya"}}],"effets":[{"gain_pari":2},{"flag":"examen-reussi","points_guilde":50,"quete":{"id":"q-ch1-appel","etape":"crypte"},"journal":"{groupe} réussissent l'examen de la Guilde : rang F."}],"choix":[],"suite":"ellipse","fin":false},"defaite":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Bon. Le golem [[t'a laminé||vous a laminés]]. » Elle soupire. « Mais [[tu t'es relevé||vous vous êtes relevés]]. C'est ce que je cherche. Rang F, à l'essai. »"},{"qui":"kaya","expression":"neutre","dit":"Kaya empoche les vingt pièces avec un grand sourire. « Sans rancune. »","si":{"flag":"pari-kaya"}}],"effets":[{"perte_pari":true},{"flag":"examen-reussi","points_guilde":20,"quete":{"id":"q-ch1-appel","etape":"crypte"},"journal":"{groupe} entrent à la Guilde « à l'essai »."}],"choix":[],"suite":"ellipse","fin":false},"ellipse":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Maintenant, au travail : contrats, entraînement, premières cicatrices. Et quand vous voudrez que les mois passent, prenez une chambre au Chaudron Fêlé. Le temps ne file que si vous le décidez. »"},{"qui":"aveline","expression":"neutre","dit":"Aveline passera souvent « par hasard » à la Guilde. Officiellement pour vous surveiller."},{"qui":"narrateur","expression":"neutre","dit":"On raconte que des lueurs étranges apparaissent parfois sous les ruines de la Crypte de la Fontaine, à l'automne. La Guilde vous y enverra en Brumaire 1013."}],"effets":[],"choix":[],"fin":true}}},"ch1-crypte":{"id":"ch1-crypte","titre":"La Crypte de la Fontaine","type":"groupe","lieu":"crypte-fontaine","decor":"crypte-entree","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"crypte"},"date_min":{"annee":1013,"mois":7,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch1-appel","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'automne est là. Des paysans ont vu des lueurs violettes sous les ruines de la Crypte de la Fontaine. Rowena [[t'a||vous a]] confié l'affaire."},{"qui":"aveline","expression":"neutre","dit":"Aveline [[t'attend||vous attend]] à l'entrée, en armure complète. « Ordre du roi : je [[t'accompagne||vous accompagne]]. Et… je n'allais pas [[te laisser descendre seul||vous laisser descendre seuls]]. »"},{"qui":"narrateur","expression":"neutre","dit":"L'escalier s'enfonce dans le noir. Une odeur d'eau croupie et de vieille pierre monte des profondeurs."}],"effets":[],"choix":[{"texte":"Descendre dans la crypte.","visible_si_bloque":false,"effets":[],"aller":"avant-descente"}],"fin":false},"avant-descente":{"parole_a":{"regle":{"classe":["ombre","archer","gardien"]},"question":{"qui":"aveline","expression":"neutre","dit":"Aveline s'arrête sur la première marche et se tourne vers {nom}. « {pseudo}, c'est toi qui ouvres la marche, ou c'est moi ? »"},"reponses":[{"texte":"« Moi. Je passe devant, sans bruit. Si quelque chose bouge, je le verrai avant qu'il nous voie. »","si":{"classe":"ombre"},"effets":[{"affinite":{"aveline":2}}],"aller":"donjon"},{"texte":"« Moi. Mon bouclier d'abord, tout le monde derrière. »","si":{"classe":"gardien"},"effets":[{"affinite":{"aveline":3}}],"aller":"donjon"},{"texte":"« Passe devant. Je couvre depuis l'arrière, une flèche encochée. »","si":{"classe":"archer"},"effets":[{"affinite":{"aveline":1}}],"aller":"donjon"},{"texte":"« Un escalier sous terre ? Laisse faire un nain. »","si":{"race":"nain"},"effets":[{"affinite":{"aveline":2}}],"aller":"donjon"},{"texte":"« Je vois dans le noir. Je guide, tu me suis. »","si":{"race":"elfe"},"effets":[{"affinite":{"aveline":2}}],"aller":"donjon"},{"texte":"« Ensemble, côte à côte. »","effets":[{"affinite":{"aveline":2}}],"aller":"donjon"},{"texte":"« Après toi, capitaine. C'est toi qui as l'armure. »","effets":[{"affinite":{"aveline":1}}],"aller":"donjon"},{"texte":"« On tire à pile ou face ? »","effets":[{"affinite":{"aveline":1}}],"aller":"donjon"}]},"repliques":[],"effets":[],"choix":[],"fin":false},"donjon":{"repliques":[],"effets":[],"choix":[],"donjon":{"id":"crypte-fontaine","sortie":"sortie"},"fin":false},"sortie":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous remontez à la surface, couverts de poussière. Dans votre sac, le sceau cendré pulse d'une lumière violette, comme un cœur."},{"qui":"aveline","expression":"colere","dit":"« Ce symbole… » Aveline pâlit. « On l'a trouvé sur les ruines de Valgrane, il y a dix ans. Le jour où mon père… » Elle se tait."}],"effets":[{"flag":"sceau-trouve","xp":60,"quete":{"id":"q-ch1-appel","etape":"lanternes"},"journal":"Dans la Crypte de la Fontaine, {groupe} découvrent un sceau cendré."}],"choix":[{"texte":"Remettre le sceau à l'Ordre, comme le veut la loi.","visible_si_bloque":false,"effets":[{"flag":"sceau-ordre","reputation":{"ordre":10}}],"aller":"ellipse"},{"texte":"Le confier à la Guilde : Rowena saura quoi en faire.","visible_si_bloque":false,"effets":[{"flag":"sceau-guilde","reputation":{"guilde":10}}],"aller":"ellipse"},{"texte":"Le garder et l'étudier vous-mêmes, en secret.","visible_si_bloque":false,"effets":[{"flag":"sceau-garde","affinite":{"aveline":2}}],"aller":"ellipse"}],"fin":false},"ellipse":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'hiver approche. Le sceau ne quitte pas vos pensées. Toute la ville parle déjà de la prochaine Fête des Lanternes, le 15 Floréal 1014."}],"effets":[],"choix":[],"fin":true}}},"ch1-lanternes":{"id":"ch1-lanternes","titre":"La Nuit des Lanternes","type":"groupe","lieu":"lysmont-place","decor":"lysmont-lanternes-nuit","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"lanternes"},"date_min":{"annee":1014,"mois":2,"jour":15}},"repetable":false,"romance":false,"quete":"q-ch1-appel","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"15 Floréal 1014, Fête des Lanternes. Des milliers de lanternes de papier s'élèvent au-dessus de Lysmont, chacune portant le nom d'un disparu."},{"qui":"bram","expression":"neutre","dit":"Bram, le tavernier, distribue des brochettes en riant. « Ce soir, c'est la maison qui régale ! »","si":{"pas_flag":"mort:bram"}},{"qui":"seraphine","expression":"neutre","dit":"Sur le balcon du château, une jeune femme blonde vous fait un petit signe discret. La princesse Séraphine."},{"qui":"aveline","expression":"neutre","dit":"Aveline est là elle aussi, en civil pour une fois, une lanterne éteinte entre les doigts."},{"qui":"aveline","expression":"gene","dit":"« C'est… pour mon père. » Elle hésite, sans vous regarder. « Vous voulez bien rester un moment ? »","si":{"affinite_min":{"aveline":20}}}],"effets":[],"choix":[{"texte":"Lâcher une lanterne avec Aveline, en silence.","si":{"affinite_min":{"aveline":20}},"visible_si_bloque":false,"effets":[{"flag":"heros:lanterne-aveline","affinite":{"aveline":6}}],"aller":"lanterne"},{"texte":"Profiter de la fête : danses, musique, brochettes.","visible_si_bloque":false,"effets":[{"affinite":{"aveline":1}}],"aller":"attaque"}],"fin":false},"lanterne":{"repliques":[{"qui":"aveline","expression":"tristesse","dit":"Vos lanternes montent côte à côte. Aveline murmure : « Il s'appelait Gauvain. Il n'était pas un traître. » Pour la première fois, sa voix tremble."},{"qui":"aveline","expression":"gene","dit":"Elle s'essuie les yeux d'un revers de main. « …Merci. N'en parlez à personne. »"}],"effets":[],"choix":[],"suite":"attaque","fin":false},"attaque":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Soudain, les lanternes virent au violet. Un cri. Puis une explosion de cendres au centre de la place."},{"qui":"narrateur","expression":"neutre","dit":"Des gobelins cendrés surgissent des égouts, guidés par des cultistes. La foule panique."},{"qui":"aveline","expression":"colere","dit":"« Protégez les civils ! » hurle Aveline en dégainant."}],"effets":[],"choix":[{"texte":"Couvrir la fuite des civils, même si les cultistes s'échappent.","visible_si_bloque":false,"effets":[{"flag":"civils-proteges","reputation":{"couronne":5},"affinite":{"aveline":5}}],"aller":"combat1"},{"texte":"Foncer sur le cultiste qui dirige l'attaque, coûte que coûte.","visible_si_bloque":false,"effets":[{"flag":["heros:civils-abandonnes","cultiste-poursuivi"],"reputation":{"guilde":5}}],"aller":"combat1"}],"fin":false},"combat1":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"lanternes-cultistes","victoire":"vorthak","defaite":"defaite1"},"fin":false},"defaite1":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous tombez sous le nombre. Quand vous rouvrez les yeux, la garde a repoussé les gobelins… mais le Chaudron Fêlé est en flammes."}],"effets":[{"pnj_mort":"bram"}],"choix":[],"suite":"vorthak","fin":false},"vorthak":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les flammes s'ouvrent. Une silhouette en armure noire s'avance, une épée nimbée de feu violet à la main."},{"qui":"vorthak","expression":"neutre","dit":"« Alors c'est vous, les nouveaux jouets de l'Ordre. » Il rit. « Le Souverain m'a demandé de vous saluer. »"},{"qui":"vorthak","expression":"neutre","dit":"« Le sceau. Vous l'avez. Je le sens. Rendez-le-moi, et je laisse vivre cette ville une année de plus. »","si":{"flag":"sceau-garde"}}],"effets":[],"choix":[{"texte":"« Viens le chercher. »","visible_si_bloque":false,"effets":[],"aller":"combat2"},{"texte":"« Pourquoi vous attaquez Lysmont ? Qu'est-ce que vous voulez vraiment ? » (Esprit, difficulté 17)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":17,"reussite":"revelation","echec":"combat2"},"effets":[]}],"fin":false},"revelation":{"repliques":[{"qui":"vorthak","expression":"neutre","dit":"Il incline la tête, amusé. « Ce que nous voulons ? Demandez à votre Grand Prieur combien coûte un Appel. Demandez-lui qui paie. »"}],"effets":[{"flag":"indice-prix-appel"}],"choix":[],"suite":"combat2","fin":false},"combat2":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"lanternes-vorthak","victoire":"victoire","defaite":"defaite2"},"fin":false},"victoire":{"repliques":[{"qui":"vorthak","expression":"neutre","dit":"Vorthak recule, son armure fendue. « Intéressant… très intéressant. » Il disparaît dans un tourbillon de cendres."},{"qui":"aveline","expression":"joie","dit":"Aveline s'appuie sur son épée, essoufflée, et vous regarde avec un sourire épuisé. « Vous… vous avez été incroyables. »"}],"effets":[{"reputation":{"couronne":10,"guilde":5},"affinite":{"aveline":4}}],"choix":[],"suite":"bilan","fin":false},"defaite2":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vorthak vous balaie comme des fétus de paille, puis s'en va, l'air ennuyé. « Revenez quand vous serez dignes de mon temps. »"}],"effets":[{"reputation":{"couronne":-5}}],"choix":[],"suite":"bilan","fin":false},"bilan":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À l'aube, Lysmont compte ses morts. Les lanternes calcinées jonchent les pavés."},{"qui":"bram","expression":"neutre","dit":"Bram, couvert de suie, vous serre la main à vous broyer les os. « Vous avez sauvé ma taverne. Ici, vous ne paierez plus jamais une bière. »","si":{"flag":"civils-proteges","pas_flag":"mort:bram"}},{"qui":"narrateur","expression":"neutre","dit":"Le Chaudron Fêlé n'est plus que cendres. Bram n'a pas survécu.","si":{"flag":"mort:bram"}}],"effets":[{"flag":"lanternes-faites","quete":{"id":"q-ch1-appel","etape":"serment"},"journal":"Fête des Lanternes : Vorthak, émissaire des Cendres, attaque Lysmont."}],"choix":[],"fin":true}}},"ch1-serment":{"id":"ch1-serment","titre":"Le Serment","type":"groupe","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"serment"},"date_min":{"annee":1014,"mois":10,"jour":3}},"repetable":false,"romance":false,"quete":"q-ch1-appel","pnj":"edmund-iv","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Nivôse 1014. La salle du trône est glaciale. Le roi Edmund IV vous toise depuis son trône doré."},{"qui":"edmund-iv","expression":"neutre","dit":"« Vous avez défendu ma capitale. Bien. Mais un héros sans maître est une épée sans fourreau : dangereux. »"},{"qui":"edmund-iv","expression":"neutre","dit":"« Agenouillez-vous et jurez fidélité à la Couronne. Vous aurez titres, or, et l'honneur de mourir pour Aubeclaire. »"},{"qui":"seraphine","expression":"neutre","dit":"La princesse Séraphine, debout à côté du trône, serre les poings. Elle croise votre regard et secoue très légèrement la tête."},{"qui":"aveline","expression":"neutre","dit":"Aveline, au garde-à-vous, fixe un point droit devant elle. Mais ses jointures blanchissent sur son épée."}],"effets":[],"choix":[{"texte":"Jurer fidélité à la Couronne.","visible_si_bloque":false,"effets":[{"flag":"serment-couronne","reputation":{"couronne":15,"guilde":-5},"affinite":{"aveline":2}}],"aller":"jure"},{"texte":"Refuser poliment : vous resterez des aventuriers libres, fidèles à la Guilde.","visible_si_bloque":false,"effets":[{"flag":"independants","reputation":{"couronne":-10,"guilde":15}}],"aller":"refus"},{"texte":"Négocier : une alliance d'égal à égal, pas un serment de vassal. (Charisme, difficulté 18)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":18,"reussite":"negociation","echec":"negociation-ratee"},"effets":[]},{"texte":"Faire semblant de jurer, en croisant les doigts dans votre dos.","visible_si_bloque":false,"effets":[{"flag":["serment-couronne","heros:parole-trahie"],"reputation":{"couronne":10}}],"aller":"faux"}],"fin":false},"jure":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"« Relevez-vous, chevaliers d'Aubeclaire. » Le roi sourit enfin. Séraphine détourne les yeux."}],"effets":[],"choix":[],"suite":"epilogue","fin":false},"refus":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"Un silence de mort. « …Soit. La Guilde répondra de vous. Ne me décevez pas. »"},{"qui":"seraphine","expression":"neutre","dit":"En sortant, Séraphine vous rattrape dans un couloir. « C'était courageux. Ou stupide. Les deux me plaisent. »"}],"effets":[],"choix":[],"suite":"epilogue","fin":false},"negociation":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"Le roi plisse les yeux… puis éclate d'un rire bref. « Vous avez du cran. Une alliance, donc. Mais je m'en souviendrai. »"}],"effets":[{"flag":"allies-libres","reputation":{"couronne":5,"guilde":5}}],"choix":[],"suite":"epilogue","fin":false},"negociation-ratee":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"« Des conditions ? À MOI ? » Le roi se lève, furieux. « Hors de ma vue ! »"}],"effets":[{"flag":"independants","reputation":{"couronne":-15,"guilde":10}}],"choix":[],"suite":"epilogue","fin":false},"faux":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous prononcez les mots du serment. Personne ne remarque vos doigts croisés… sauf Aveline, juste derrière vous. Son visage se ferme."}],"effets":[],"choix":[],"suite":"epilogue","fin":false},"epilogue":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Ce soir-là, sur les remparts, vous regardez les étoiles d'un ciel qui n'est pas le vôtre."},{"qui":"aveline","expression":"neutre","dit":"« Le printemps prochain, on m'envoie à la frontière sud. » Aveline hésite. « J'aimerais… que vous veniez. » Elle rougit. « Pour la mission, évidemment. »","si":{"affinite_min":{"aveline":35}}},{"qui":"narrateur","expression":"neutre","dit":"Deux ans ont passé depuis l'Appel. Velmaris n'est plus un monde étranger : c'est le vôtre, désormais. Et il brûle déjà au nord."}],"effets":[{"xp":150,"terminer_quete":"q-ch1-appel"},{"fin_chapitre":1}],"choix":[],"fin":true}}},"sq-loups-guilde":{"id":"sq-loups-guilde","titre":"Les loups de la Combe : l'affaire","type":"groupe","lieu":"guilde","decor":"guilde","debut":"debut","disponible_si":{"flag":"examen-reussi","pas_flag":"loups-acceptes"},"repetable":false,"romance":false,"quete":"q-loups","pnj":"rowena","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Un fermier de la Combe-aux-Saules, Gareth, perd ses moutons. Il n'a pas de quoi payer un vrai contrat, alors personne n'y va. » Rowena [[te||vous]] regarde par-dessus sa pipe. « Sauf si ça [[t'intéresse||vous intéresse]]. »"}],"effets":[],"choix":[{"texte":"« [[J'y vais||On y va]]. »","visible_si_bloque":false,"effets":[{"flag":"loups-acceptes","quete":{"id":"q-loups","etape":"ferme"}}],"aller":"accepte"}],"fin":false},"accepte":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« La ferme est au sud-ouest, à l'entrée de la Combe. Et [[reviens||revenez]] me dire comment ça s'est fini. »"}],"effets":[],"choix":[],"fin":true}}},"sq-loups-ferme":{"id":"sq-loups-ferme","titre":"Les loups de la Combe : la ferme de Gareth","type":"groupe","lieu":"combe-aux-saules","decor":"combe-aux-saules","debut":"debut","disponible_si":{"quete_etape":{"q-loups":"ferme"}},"repetable":false,"romance":false,"quete":"q-loups","pnj":"gareth","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"gareth","expression":"neutre","dit":"« Trois moutons cette semaine ! Et hier, ma petite Rose a vu des yeux jaunes à la lisière. » Gareth tord son chapeau de paille entre ses mains."},{"qui":"gareth","expression":"neutre","dit":"« Les traces partent de l'enclos vers les ronces, là-bas. Moi, je n'ose plus y aller. »"}],"effets":[{"quete":{"id":"q-loups","etape":"traces"}}],"choix":[],"fin":true}}},"sq-loups-traces":{"id":"sq-loups-traces","titre":"Les loups de la Combe : les traces","type":"groupe","lieu":"combe-lisiere","decor":"combe-aux-saules","debut":"debut","disponible_si":{"quete_etape":{"q-loups":"traces"}},"repetable":false,"romance":false,"quete":"q-loups","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À la lisière, la terre est retournée. Des empreintes larges comme une main… et d'autres, toutes petites, à côté."}],"effets":[],"choix":[{"texte":"Suivre les grandes empreintes.","visible_si_bloque":false,"effets":[],"aller":"grandes"},{"texte":"Regarder de plus près les petites.","visible_si_bloque":false,"effets":[{"flag":"louveteaux-vus"}],"aller":"petites"}],"fin":false},"grandes":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La piste est franche : elle file droit vers un énorme saule, au fond de la Combe."}],"effets":[{"quete":{"id":"q-loups","etape":"taniere"}}],"choix":[],"fin":true},"petites":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Des louveteaux. La meute ne chasse pas par plaisir : elle nourrit ses petits. La piste mène à un énorme saule, au fond de la Combe."}],"effets":[{"xp":10,"quete":{"id":"q-loups","etape":"taniere"}}],"choix":[],"fin":true}}},"sq-loups":{"id":"sq-loups","titre":"Les loups de la Combe : le vieux saule","type":"groupe","lieu":"combe-taniere","decor":"combe-aux-saules","debut":"debut","disponible_si":{"quete_etape":{"q-loups":"taniere"}},"repetable":false,"romance":false,"quete":"q-loups","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Une tanière s'ouvre sous les racines du vieux saule. Des grognements… et des gémissements plus aigus : des louveteaux."}],"effets":[],"choix":[{"texte":"Attaquer la meute.","visible_si_bloque":false,"effets":[],"aller":"combat"},{"texte":"Utiliser votre don pour parler à la louve. (Langue universelle)","si":{"don":"langue-universelle"},"visible_si_bloque":false,"effets":[],"aller":"parler"},{"texte":"Effrayer la meute avec du feu et du bruit pour la faire partir. (Force, difficulté 16)","visible_si_bloque":false,"test":{"carac":"FOR","difficulte":16,"reussite":"fuite","echec":"combat"},"effets":[]}],"fin":false},"parler":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La louve vous écoute, babines retroussées. Puis, lentement, elle comprend : les fermiers, les pièges, les bois plus au sud où le gibier abonde."},{"qui":"narrateur","expression":"neutre","dit":"À l'aube, la meute est partie. Gareth n'en croit pas ses yeux."}],"effets":[{"flag":"loups-sauves","xp":80}],"choix":[],"suite":"fin","fin":false},"fuite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Torches, cris, casseroles : la meute détale vers le sud avec ses petits. Aucun sang versé."}],"effets":[{"flag":"loups-sauves","xp":60}],"choix":[],"suite":"fin","fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"loups-alpha","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La meute est décimée. Les louveteaux s'enfuient dans les fourrés."}],"effets":[],"choix":[],"suite":"fin","fin":false},"defaite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les loups vous repoussent. Gareth vous traîne jusqu'à sa ferme et vous soigne avec une soupe épaisse. « On réessaiera. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le calme revient sur la Combe. Il reste à prévenir Gareth… et Rowena, à la Guilde."}],"effets":[{"quete":{"id":"q-loups","etape":"retour"}}],"choix":[],"fin":true}}},"sq-loups-retour":{"id":"sq-loups-retour","titre":"Les loups de la Combe : le compte rendu","type":"groupe","lieu":"guilde","decor":"guilde","debut":"debut","disponible_si":{"quete_etape":{"q-loups":"retour"}},"repetable":false,"romance":false,"quete":"q-loups","pnj":"rowena","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Alors, ces loups ? »"},{"qui":"rowena","expression":"neutre","dit":"« Partis sans une goutte de sang ? » Elle hausse un sourcil. « C'est rare, ça. Et ça me plaît. »","si":{"flag":"loups-sauves"}},{"qui":"gareth","expression":"neutre","dit":"Gareth a fait le chemin jusqu'à la Guilde, son chapeau à la main. « Merci, du fond du cœur. Tenez, c'est pas grand-chose, mais c'est honnête. »"}],"effets":[{"reputation":{"guilde":3},"or":25,"points_guilde":30,"terminer_quete":"q-loups"}],"choix":[],"fin":true}}},"sq-reliques":{"id":"sq-reliques","titre":"Le marchand de reliques","type":"groupe","lieu":"taverne","decor":"taverne","debut":"debut","disponible_si":{"flag":"examen-reussi"},"repetable":false,"romance":false,"quete":"q-reliques","pnj":"ferrand","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ferrand","expression":"neutre","dit":"« Approchez, approchez ! Un os authentique de Saint Aldebrand, le Premier Appelé ! Il guérit les fièvres et porte chance aux aventuriers. Cent pièces seulement ! »"},{"qui":"bram","expression":"neutre","dit":"Bram lève les yeux au ciel derrière son comptoir. « Ça fait trois semaines qu'il vend des os de poulet. »","si":{"pas_flag":"mort:bram"}}],"effets":[{"quete":{"id":"q-reliques","etape":"enqueter"}}],"choix":[{"texte":"Examiner la « relique » de près. (Intelligence, difficulté 15)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":15,"reussite":"demasque","echec":"rate"},"effets":[]},{"texte":"L'acheter. On ne sait jamais.","si":{"or_min":100},"visible_si_bloque":false,"effets":[{"or":-100,"objet":"relique-douteuse"}],"aller":"achete"},{"texte":"Aller prévenir l'Ordre : vendre de fausses reliques est un crime.","visible_si_bloque":false,"effets":[],"aller":"ordre"}],"fin":false},"demasque":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un os de poulet, verni et gravé à la hâte. Vous le brandissez sous le nez des clients. Rires, huées : Ferrand s'enfuit sous les quolibets."}],"effets":[{"flag":"ferrand-demasque","reputation":{"guilde":5},"xp":50}],"choix":[],"suite":"fin","fin":false},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'os a l'air… vrai ? Vous n'en êtes pas sûrs. Ferrand vous adresse un clin d'œil satisfait."}],"effets":[],"choix":[],"suite":"fin","fin":false},"achete":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Ferrand empoche l'or avec un sourire radieux. La relique sent vaguement le poulet rôti."}],"effets":[],"choix":[],"suite":"fin","fin":false},"ordre":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"Sœur Elianne arrive en personne, le visage grave. « Ces escrocs salissent la mémoire des Appelés. Merci. » Ferrand est emmené par deux gardes."}],"effets":[{"flag":"ferrand-arrete","reputation":{"ordre":8},"xp":40}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[{"points_guilde":15,"terminer_quete":"q-reliques"}],"choix":[],"fin":true}}},"sq-tanneurs-plainte":{"id":"sq-tanneurs-plainte","titre":"Les disparus des Tanneurs : la plainte","type":"groupe","lieu":"quartier-tanneurs","decor":"quartier-tanneurs","debut":"debut","disponible_si":{"flag":"examen-reussi","pas_flag":"tanneurs-commence"},"repetable":false,"romance":false,"quete":"q-tanneurs","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les ruelles des Tanneurs sentent l'urine et la teinture. Une mère [[t'agrippe||vous agrippe]] le bras : « Ma fille, Lina. Partie chercher de l'eau il y a trois jours. »"},{"qui":"narrateur","expression":"neutre","dit":"« La garde ne vient plus ici. Je n'ai que [[toi||vous]]. »"}],"effets":[{"flag":"tanneurs-commence","quete":{"id":"q-tanneurs","etape":"piste"}}],"choix":[],"fin":true}}},"sq-tanneurs-piste":{"id":"sq-tanneurs-piste","titre":"Les disparus des Tanneurs : la piste","type":"groupe","lieu":"quartier-tanneurs","decor":"quartier-tanneurs","debut":"debut","disponible_si":{"quete_etape":{"q-tanneurs":"piste"}},"repetable":false,"romance":false,"quete":"q-tanneurs","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Près du puits, un seau renversé. Des traces de pas, une odeur de soufre."},{"qui":"narrateur","expression":"neutre","dit":"Et, gravé sur une porte, un symbole violet que [[tu commences||vous commencez]] à connaître.","si":{"flag":"sceau-trouve"}}],"effets":[],"choix":[{"texte":"Suivre la piste de soufre. (Esprit, difficulté 14)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":14,"reussite":"piste","echec":"retard"},"effets":[]},{"texte":"Interroger les ivrognes du coin, avec quelques pièces. (Charisme, difficulté 13)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":13,"reussite":"piste","echec":"retard"},"effets":[]}],"fin":false},"piste":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La piste mène à une tannerie abandonnée, au bout de la ruelle. Sous la trappe de la cave : des chants étouffés."}],"effets":[{"flag":"tanneurs-piste-fraiche","quete":{"id":"q-tanneurs","etape":"cave"}}],"choix":[],"fin":true},"retard":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Des heures précieuses sont perdues. À la nuit tombée seulement, quelqu'un parle enfin d'une tannerie abandonnée, au bout de la ruelle."}],"effets":[{"quete":{"id":"q-tanneurs","etape":"cave"}}],"choix":[],"fin":true}}},"sq-tanneurs":{"id":"sq-tanneurs","titre":"Les disparus des Tanneurs : la cave","type":"groupe","lieu":"tannerie-abandonnee","decor":"quartier-tanneurs","debut":"debut","disponible_si":{"quete_etape":{"q-tanneurs":"cave"}},"repetable":false,"romance":false,"quete":"q-tanneurs","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La trappe est lourde, mais ses gonds sont graissés de frais. En bas : des cages, des bougies violettes."}],"effets":[],"choix":[{"texte":"Descendre dans la cave.","si":{"flag":"tanneurs-piste-fraiche"},"visible_si_bloque":false,"effets":[],"aller":"piste"},{"texte":"Descendre dans la cave.","si":{"pas_flag":"tanneurs-piste-fraiche"},"visible_si_bloque":false,"effets":[],"aller":"retard"}],"fin":false},"piste":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les cultistes sont en plein rituel et ne [[t'ont pas entendu||vous ont pas entendus]]. Lina est vivante, dans la cage du fond."}],"effets":[],"choix":[],"combat":{"rencontre":"tanneurs-cultistes","victoire":"sauvee","defaite":"echec"},"fin":false},"retard":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Trop de temps a passé : les cultistes [[t'attendent||vous attendent]] au pied de l'échelle."}],"effets":[],"choix":[],"combat":{"rencontre":"tanneurs-cultistes","victoire":"trop-tard","defaite":"echec"},"fin":false},"sauvee":{"repliques":[{"qui":"lina","expression":"neutre","dit":"Lina se jette dans les bras de sa mère en pleurant. Les deux autres disparus sont là aussi, affaiblis mais vivants."}],"effets":[{"flag":"lina-sauvee","reputation":{"couronne":5,"guilde":5},"xp":70}],"choix":[],"suite":"fin","fin":false},"trop-tard":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les cultistes sont vaincus. Deux prisonniers sont sauvés… mais pour Lina, il est trop tard. Sa mère s'effondre."}],"effets":[{"xp":50,"pnj_mort":"lina"}],"choix":[],"suite":"fin","fin":false},"echec":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous êtes repoussés. Quand la garde investit la cave le lendemain, elle est vide. On ne retrouvera jamais Lina."}],"effets":[{"reputation":{"couronne":-5},"pnj_mort":"lina"}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Il faut que la Guilde sache ce qui se cachait sous cette tannerie."}],"effets":[{"flag":"cultistes-lysmont","quete":{"id":"q-tanneurs","etape":"retour"}}],"choix":[],"fin":true}}},"sq-tanneurs-retour":{"id":"sq-tanneurs-retour","titre":"Les disparus des Tanneurs : le rapport","type":"groupe","lieu":"guilde","decor":"guilde","debut":"debut","disponible_si":{"quete_etape":{"q-tanneurs":"retour"}},"repetable":false,"romance":false,"quete":"q-tanneurs","pnj":"rowena","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"Rowena écoute sans un mot, puis repose sa pipe. « Des cultistes des Cendres. Dans MA ville. » Elle griffonne un ordre pour la garde."},{"qui":"rowena","expression":"neutre","dit":"« La petite Lina est rentrée chez elle. C'est grâce à [[toi||vous]]. »","si":{"flag":"lina-sauvee"}}],"effets":[{"points_guilde":30,"terminer_quete":"q-tanneurs"}],"choix":[],"fin":true}}},"sq-apprenti":{"id":"sq-apprenti","titre":"L'apprenti de l'Ordre","type":"groupe","lieu":"temple-du-seuil","decor":"temple-du-seuil","debut":"debut","disponible_si":{"flag":"examen-reussi"},"repetable":false,"romance":false,"quete":"q-apprenti","pnj":"elianne","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"« Tobin, mon apprenti, passe ses nuits dans les archives interdites. S'il se fait prendre par le Grand Prieur… » Sœur Elianne se mord la lèvre. « Pouvez-vous lui parler ? »"},{"qui":"tobin","expression":"neutre","dit":"Vous trouvez Tobin entre deux rayonnages, une bougie à la main, un vieux registre ouvert. « Regardez ! Les registres de l'Appel. Il manque des pages. Toujours les mêmes : le prix. »"}],"effets":[{"quete":{"id":"q-apprenti","etape":"parler"}}],"choix":[{"texte":"Lire le registre avec lui.","visible_si_bloque":false,"effets":[{"flag":"indice-prix-appel","xp":30}],"aller":"lire"},{"texte":"Le convaincre de remettre le registre en place avant qu'il ne soit trop tard.","visible_si_bloque":false,"effets":[{"reputation":{"ordre":5}}],"aller":"raisonner"},{"texte":"Le dénoncer au Grand Prieur Auréliath.","visible_si_bloque":false,"effets":[{"flag":"tobin-denonce","reputation":{"ordre":10}}],"aller":"denonce"}],"fin":false},"lire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Une seule ligne a échappé au grattoir : « …et pour chaque Appel, le Voile cède d'un fil, et au nord, les Cendres s'en nourrissent. »"},{"qui":"elianne","expression":"surprise","dit":"Elianne, derrière vous, a tout entendu. Elle est livide."}],"effets":[],"choix":[],"suite":"fin","fin":false},"raisonner":{"repliques":[{"qui":"tobin","expression":"neutre","dit":"Tobin soupire et range le registre. « Vous avez raison. Mais un jour, quelqu'un devra savoir. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"denonce":{"repliques":[{"qui":"aureliath","expression":"neutre","dit":"Le Grand Prieur vous remercie chaleureusement. Le lendemain, Tobin a été « envoyé dans un monastère du nord ». Elianne ne vous adresse plus la parole."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[{"points_guilde":15,"terminer_quete":"q-apprenti"}],"choix":[],"fin":true}}},"sq-tournoi-inscription":{"id":"sq-tournoi-inscription","titre":"Le tournoi des écuyers : l'inscription","type":"groupe","lieu":"arene","decor":"arene","debut":"debut","disponible_si":{"flag":"examen-reussi","pas_flag":"tournoi-inscrit"},"repetable":false,"romance":false,"quete":"q-tournoi","pnj":"aveline","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Aveline, juge du tournoi, [[t'accueille||vous accueille]]. « Un de nos écuyers s'est cassé la jambe. Il me faut un remplaçant. Et un adversaire coriace pour le finaliste : un mercenaire qui triche. »"},{"qui":"aveline","expression":"gene","dit":"« Si [[tu gagnes… je t'offre||vous gagnez… je vous offre]] une pâtisserie. » Elle se racle la gorge. « C'est une coutume. »"},{"qui":"aveline","expression":"neutre","dit":"« Il traîne sur la place avant chaque combat. [[Va||Allez]] voir comment il s'y prend, puis [[reviens||revenez]] ici. »"}],"effets":[{"flag":"tournoi-inscrit","quete":{"id":"q-tournoi","etape":"reperer"}}],"choix":[],"fin":true}}},"sq-tournoi-reperage":{"id":"sq-tournoi-reperage","titre":"Le tournoi des écuyers : le tricheur","type":"groupe","lieu":"lysmont-place","decor":"lysmont-place","debut":"debut","disponible_si":{"quete_etape":{"q-tournoi":"reperer"}},"repetable":false,"romance":false,"quete":"q-tournoi","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le mercenaire est là, près de la fontaine, entouré de parieurs. Un grand gaillard au sourire trop sûr de lui."}],"effets":[],"choix":[{"texte":"L'observer de loin pendant qu'il s'échauffe.","visible_si_bloque":false,"effets":[],"aller":"observe"},{"texte":"Payer un verre à l'un de ses anciens adversaires.","visible_si_bloque":false,"effets":[],"aller":"verre"}],"fin":false},"observe":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Il glisse quelque chose dans son gant gauche avant chaque passe : une poignée de sable. Maintenant, [[tu sais||vous savez]] d'où viendra le coup bas."}],"effets":[{"xp":10,"quete":{"id":"q-tournoi","etape":"duel"}}],"choix":[],"fin":true},"verre":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"« Il vise les yeux. Du sable, toujours de la main gauche. » L'écuyer vide sa chope. « Et il frappe quand on recule. »"}],"effets":[{"xp":10,"quete":{"id":"q-tournoi","etape":"duel"}}],"choix":[],"fin":true}}},"sq-tournoi":{"id":"sq-tournoi","titre":"Le tournoi des écuyers : le duel","type":"groupe","lieu":"arene","decor":"arene","debut":"debut","disponible_si":{"quete_etape":{"q-tournoi":"duel"}},"repetable":false,"romance":false,"quete":"q-tournoi","pnj":"aveline","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"« [[Te||Vous]] voilà. Le finaliste est prêt. » Aveline baisse la voix. « Méfie-toi de sa main gauche. »"}],"effets":[],"choix":[{"texte":"Entrer en lice.","visible_si_bloque":false,"effets":[],"aller":"combat"}],"fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"tournoi-ecuyers","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La foule rugit. Le mercenaire, désarmé, est escorté hors de l'arène."},{"qui":"aveline","expression":"joie","dit":"Aveline vous tend un gâteau de Lysmont, les joues roses. « Coutume. C'est la coutume. »"}],"effets":[{"reputation":{"couronne":5},"affinite":{"aveline":6},"or":40,"objet":"gateau-lysmont"}],"choix":[],"suite":"fin","fin":false},"defaite":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"« Il trichait, je l'ai vu. » Aveline fait disqualifier le mercenaire. « Vous vous êtes battus honnêtement. C'est ce qui compte. »"}],"effets":[{"affinite":{"aveline":3}}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[{"points_guilde":25,"terminer_quete":"q-tournoi"}],"choix":[],"fin":true}}},"sq-boutique":{"id":"sq-boutique","titre":"Premiers pas au Comptoir","type":"individuel","lieu":"boutique","decor":"boutique","debut":"debut","disponible_si":{"flag":"examen-reussi","pas_flag":"boutique-decouverte"},"repetable":false,"romance":false,"quete":"q-boutique","pnj":"halvine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"halvine","expression":"neutre","dit":"« Un nouveau visage de la Guilde ! Entrez, entrez. Dame Halvine Corbelet, pour vous servir. Ici, tout a un prix, et le prix est juste. »"},{"qui":"halvine","expression":"neutre","dit":"« C'est simple : l'onglet Acheter montre ce que je vends, l'onglet Vendre montre ce que vous avez dans votre sac. Je reprends tout à moitié prix, sauf les objets de quête. »"},{"qui":"narrateur","expression":"neutre","dit":"En vous penchant vers le comptoir, vous remarquez quelque chose qui brille entre deux pavés : une vieille breloque de cuivre."},{"qui":"halvine","expression":"neutre","dit":"« Tiens, ça traîne là depuis des semaines. Gardez-la. Achetez-moi d'abord quelque chose d'utile, une petite potion par exemple, puis revendez-moi cette breloque : vous saurez tout faire. »"}],"effets":[{"flag":"boutique-decouverte","objet":"breloque-cabossee","quete":{"id":"q-boutique","etape":"acheter"}}],"choix":[],"fin":true}}},"sq-boutique-fin":{"id":"sq-boutique-fin","titre":"Premiers pas au Comptoir : le compte est bon","type":"individuel","lieu":"boutique","decor":"boutique","debut":"debut","disponible_si":{"quete_etape":{"q-boutique":"retour"}},"repetable":false,"romance":false,"quete":"q-boutique","pnj":"halvine","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"halvine","expression":"neutre","dit":"« Acheté, vendu, et sans vous faire rouler : vous apprenez vite. » Elle pousse une petite fiole et quelques pièces vers vous."},{"qui":"halvine","expression":"neutre","dit":"« Cadeau de la maison. Revenez quand votre bourse sera plus lourde : j'ai toujours de quoi l'alléger. »"}],"effets":[{"xp":20,"or":15,"objet":"potion-soin-petite","terminer_quete":"q-boutique"}],"choix":[],"fin":true}}},"cl-lame-runique-1":{"id":"cl-lame-runique-1","titre":"Lame runique — La rune perdue","type":"individuel","lieu":"qarzim-bazar","decor":"qarzim-bazar","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"lame-runique"},"repetable":false,"romance":false,"quete":"q-classe-lame-runique","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au fond du Bazar, un marchand de curiosités vend un morceau de colonne de sel. Une rune y est gravée : un cercle fendu, entouré de sept traits."},{"qui":"narrateur","expression":"neutre","dit":"Votre lame vibre quand vous approchez la main. Les runes que vous gravez en combat ont toujours été les vôtres… mais celle-ci, votre lame la connaît."}],"effets":[],"choix":[{"texte":"Recopier la rune et la graver sur votre lame. (Intelligence, difficulté 20)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":20,"reussite":"gravee","echec":"brulure"},"effets":[]},{"texte":"Acheter le fragment de colonne. (60 or)","si":{"or_min":60},"visible_si_bloque":false,"effets":[{"or":-60}],"aller":"gravee"}],"fin":false},"gravee":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La rune s'imprime dans l'acier comme si elle l'attendait. Pendant une seconde, vous voyez mille sceaux s'allumer le long de la lame, puis s'éteindre."},{"qui":"narrateur","expression":"neutre","dit":"Le marchand murmure : « Les nains de Karak-Dûm savent forger ces runes-là. On dit qu'ils les tiennent des tout premiers Appelés. »"}],"effets":[{"flag":"heros:classe-1","xp":200,"quete":{"id":"q-classe-lame-runique","etape":"etape2"}}],"choix":[],"fin":true},"brulure":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La rune vous brûle la main avant de s'imprimer dans l'acier, de travers. Elle tiendra. Elle n'aime pas qu'on la force."}],"effets":[{"flag":"heros:classe-1","xp":120,"quete":{"id":"q-classe-lame-runique","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-arcaniste-1":{"id":"cl-arcaniste-1","titre":"Arcaniste — Le feu du désert","type":"individuel","lieu":"qarzim-porte","decor":"qarzim-porte","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"arcaniste"},"repetable":false,"romance":false,"quete":"q-classe-arcaniste","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un ermite aux yeux brûlés par le soleil mendie à la Porte des Caravanes. Quand vous passez, des étincelles bleues courent au bout de vos doigts. Il sourit."},{"qui":"narrateur","expression":"neutre","dit":"« Tu sens la foudre des tempêtes, toi. Viens. Je vais te montrer comment on la boit. »"}],"effets":[],"choix":[{"texte":"Le suivre dans le désert, au cœur d'une tempête sèche.","visible_si_bloque":false,"effets":[],"aller":"tempete"}],"fin":false},"tempete":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au milieu des dunes, l'air crépite. L'ermite lève les bras ; un éclair tombe… dans ses mains, sans le blesser. « À toi. »"}],"effets":[],"choix":[{"texte":"Attraper l'éclair. (Esprit, difficulté 21)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":21,"reussite":"reussi","echec":"foudroye"},"effets":[]}],"fin":false},"reussi":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La foudre vous traverse sans vous brûler. Vous la sentez couler, comme une rivière, puis se ranger quelque part en vous, à côté du feu et du givre."},{"qui":"narrateur","expression":"neutre","dit":"« Il te manque le feu de la terre, maintenant. Celui des volcans. Va voir les nains, à Grisfer. »"}],"effets":[{"flag":"heros:classe-1","xp":200,"quete":{"id":"q-classe-arcaniste","etape":"etape2"}}],"choix":[],"fin":true},"foudroye":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'éclair vous jette dans le sable, les cheveux fumants. Mais quelque chose est resté. Une étincelle qui ne s'éteint pas."}],"effets":[{"flag":"heros:classe-1","xp":120,"quete":{"id":"q-classe-arcaniste","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-invocateur-1":{"id":"cl-invocateur-1","titre":"Invocateur — Le pacte des bêtes","type":"individuel","lieu":"campement-lunecroc","decor":"campement-lunecroc","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"invocateur"},"repetable":false,"romance":false,"quete":"q-classe-invocateur","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La nuit, au campement, un fennec translucide s'assoit devant votre tente. Un esprit. Il vous regarde comme on regarde un voleur."},{"qui":"sorha","expression":"neutre","dit":"L'Ancienne Sorha vous chuchote : « Tes créatures obéissent parce que tu les tires du Voile. Lui, il veut savoir si tu sais demander. »"}],"effets":[],"choix":[{"texte":"S'asseoir devant lui et lui parler, longtemps. (Charisme, difficulté 19)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":19,"reussite":"pacte","echec":"fuite"},"effets":[]},{"texte":"Tenter de l'invoquer de force.","visible_si_bloque":false,"effets":[],"aller":"force"}],"fin":false},"pacte":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le fennec écoute toute la nuit. À l'aube, il pose une patte sur votre main. Vos créatures, désormais, vous semblent… plus chaudes. Plus présentes."}],"effets":[{"flag":"heros:classe-1","xp":200,"quete":{"id":"q-classe-invocateur","etape":"etape2"}}],"choix":[],"fin":true},"fuite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le fennec repart dans la nuit. Mais au loin, il se retourne une fois. Ce n'est pas un non. C'est un « pas encore »."}],"effets":[{"flag":"heros:classe-1","xp":120,"quete":{"id":"q-classe-invocateur","etape":"etape2"}}],"choix":[],"fin":true},"force":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'esprit se tord, vous mord la main, et disparaît. Sorha secoue la tête. « On ne met pas un vent en cage. » Vous avez compris la leçon, à vos dépens."}],"effets":[{"flag":"heros:classe-1","xp":80,"quete":{"id":"q-classe-invocateur","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-ombre-1":{"id":"cl-ombre-1","titre":"Ombre — La Main et l'Ombre","type":"individuel","lieu":"qarzim-porte","decor":"qarzim-porte","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"ombre"},"repetable":false,"romance":false,"quete":"q-classe-ombre","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un grain de sable sur votre oreiller, un soir. Puis un mot, glissé sous la porte : « Les toits. Minuit. Seul. »"},{"qui":"narrateur","expression":"neutre","dit":"Sur les toits, trois silhouettes voilées de la Main de Sable vous attendent. « Tu as le talent. Nous avons l'or. Montre-nous ce que vaut une Ombre de l'autre monde. »"}],"effets":[],"choix":[{"texte":"Accepter l'épreuve : leur voler leurs insignes sans être vu. (Agilité, difficulté 21)","visible_si_bloque":false,"test":{"carac":"AGI","difficulte":21,"reussite":"vol","echec":"combat"},"effets":[]},{"texte":"Refuser et combattre.","visible_si_bloque":false,"effets":[],"aller":"combat"}],"fin":false},"vol":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À l'aube, les trois assassins se réveillent sans leurs insignes, posés en rang sur le toit… avec un mot : « Non merci. »"},{"qui":"narrateur","expression":"neutre","dit":"Une voix, derrière vous, que vous n'avez pas entendue venir : « Pas mal. Kezir avait un maître, autrefois. Il vit dans l'Archipel. Si tu veux devenir meilleur que lui… »"}],"effets":[{"flag":"heros:classe-1","xp":220,"quete":{"id":"q-classe-ombre","etape":"etape2"}}],"choix":[],"fin":true},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"assassins-banquet","victoire":"fini","defaite":"fini"},"fin":false},"fini":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les assassins disparaissent dans la nuit. L'un d'eux a laissé tomber un mot : « Le maître de Kezir vit dans l'Archipel des Brumes. »"}],"effets":[{"flag":"heros:classe-1","xp":160,"quete":{"id":"q-classe-ombre","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-gardien-1":{"id":"cl-gardien-1","titre":"Gardien — Le serment du bouclier","type":"individuel","lieu":"qarzim-oasis","decor":"qarzim-oasis","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"gardien"},"repetable":false,"romance":false,"quete":"q-classe-gardien","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ziyane","expression":"neutre","dit":"Mère Ziyane vous indique un vieil homme au fond de l'auberge. « Il vient tous les soirs boire de l'eau, rien d'autre. On dit qu'il était paladin de l'Ordre. »"},{"qui":"narrateur","expression":"neutre","dit":"Le vieil homme a un bouclier rond posé contre sa chaise. Pas de blason : on l'a gratté. « Tu portes la lumière de l'Ordre, toi aussi. Sais-tu seulement ce qu'elle protège ? »"}],"effets":[],"choix":[{"texte":"« Les gens. Pas l'Ordre. »","visible_si_bloque":false,"effets":[],"aller":"gens"},{"texte":"« L'Ordre protège les gens. C'est la même chose. »","visible_si_bloque":false,"effets":[],"aller":"ordre"}],"fin":false},"gens":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le vieil homme sourit pour la première fois. Il vous tend son bouclier. « Tiens-le contre moi. » Il frappe, une fois, de toutes ses forces."}],"effets":[],"choix":[{"texte":"Tenir. (Vitalité, difficulté 20)","visible_si_bloque":false,"test":{"carac":"VIT","difficulte":20,"reussite":"tenu","echec":"tombe"},"effets":[]}],"fin":false},"ordre":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"« J'ai cru ça aussi. Jusqu'à Valgrane. » Il se tait, puis vous tend son bouclier. « Tiens-le. Si tu tiens, je te dirai le reste. »"}],"effets":[],"choix":[{"texte":"Tenir. (Vitalité, difficulté 20)","visible_si_bloque":false,"test":{"carac":"VIT","difficulte":20,"reussite":"tenu","echec":"tombe"},"effets":[]}],"fin":false},"tenu":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous tenez. Le vieil homme hoche la tête. « Le vrai serment du bouclier ne se prête pas au temple. Il se prête sur une passe, face à l'ennemi. Il y a une passe, dans les Mille Marches, à Grisfer… »"}],"effets":[{"flag":"heros:classe-1","xp":200,"quete":{"id":"q-classe-gardien","etape":"etape2"}}],"choix":[],"fin":true},"tombe":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous voilà assis par terre. Le vieil homme vous aide à vous relever. « Tu t'es relevé. C'est le début. » Il vous parle d'une passe, dans les Mille Marches, à Grisfer."}],"effets":[{"flag":"heros:classe-1","xp":120,"quete":{"id":"q-classe-gardien","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-alchimiste-1":{"id":"cl-alchimiste-1","titre":"Alchimiste — L'atelier d'airain","type":"individuel","lieu":"qarzim-bazar","decor":"qarzim-bazar","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"alchimiste"},"repetable":false,"romance":false,"quete":"q-classe-alchimiste","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au fond du Bazar, un atelier sent l'huile et le métal chaud. Sur l'établi, les plans d'un automate de la taille d'un homme : un « golem d'airain ». Il manque la page du cœur."},{"qui":"narrateur","expression":"neutre","dit":"Le vieux vulpin qui tient l'atelier soupire. « Mon maître a emporté la page du cœur dans sa tombe. Il disait que seul un cœur de forge nain pouvait faire battre l'airain. »"}],"effets":[],"choix":[{"texte":"Reconstituer la page manquante à partir des autres. (Intelligence, difficulté 21)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":21,"reussite":"plans","echec":"bricolage"},"effets":[]},{"texte":"Racheter les plans tels quels. (80 or)","si":{"or_min":80},"visible_si_bloque":false,"effets":[{"or":-80}],"aller":"bricolage"}],"fin":false},"plans":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À l'aube, la page est là, recopiée de votre main : les engrenages, les soupapes, et au centre, un cercle vide marqué « cœur de forge — Karak-Dûm »."}],"effets":[{"flag":"heros:classe-1","xp":200,"objet":"bombe-feu","quete":{"id":"q-classe-alchimiste","etape":"etape2"}}],"choix":[],"fin":true},"bricolage":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les plans sous le bras, vous savez ce qu'il vous faut : un cœur de forge, et la seule forge qui en fabrique est à Karak-Dûm, dans les Monts Grisfer."}],"effets":[{"flag":"heros:classe-1","xp":140,"quete":{"id":"q-classe-alchimiste","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-archer-1":{"id":"cl-archer-1","titre":"Archer — Le chant des ancêtres","type":"individuel","lieu":"campement-lunecroc","decor":"campement-lunecroc","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"archer"},"repetable":false,"romance":false,"quete":"q-classe-archer","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"sorha","expression":"neutre","dit":"L'Ancienne Sorha pose une plume blanche sur votre arc. « Les ancêtres guident les flèches de ceux qui écoutent le vent. Ferme les yeux. Tire sur le chacal qui rôde là-bas, sans le regarder. »"}],"effets":[],"choix":[{"texte":"Fermer les yeux et tirer. (Esprit, difficulté 20)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":20,"reussite":"touche","echec":"rate"},"effets":[]}],"fin":false},"touche":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous entendez la flèche chanter. Puis un jappement, au loin : touché. Sorha rit doucement. « Les ancêtres t'aiment bien. »"},{"qui":"sorha","expression":"neutre","dit":"« Il y a, dans l'Archipel des Brumes, une cible que le vent déplace sans cesse. Celui qui la touche entend les ancêtres pour toujours. »"}],"effets":[{"flag":"heros:classe-1","xp":200,"quete":{"id":"q-classe-archer","etape":"etape2"}}],"choix":[],"fin":true},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La flèche se plante dans le sable. Sorha hausse les épaules. « Le vent n'a pas encore appris ton nom. Il l'apprendra. » Elle vous parle de la cible des vents, dans l'Archipel des Brumes."}],"effets":[{"flag":"heros:classe-1","xp":120,"quete":{"id":"q-classe-archer","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-guerisseur-1":{"id":"cl-guerisseur-1","titre":"Guérisseur — Le souffle des vivants","type":"individuel","lieu":"mines-ether","decor":"mines-ether","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"guerisseur"},"repetable":false,"romance":false,"quete":"q-classe-guerisseur","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Aux mines, des mineurs toussent une poussière violette. Les guérisseurs de la Concorde passent devant eux sans s'arrêter : « Ce ne sont que des journaliers. »"},{"qui":"narrateur","expression":"neutre","dit":"Un enfant vous tire par la manche. Son père ne respire presque plus."}],"effets":[],"choix":[{"texte":"Soigner les mineurs toute la nuit. (Esprit, difficulté 21)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":21,"reussite":"sauves","echec":"epuise"},"effets":[]}],"fin":false},"sauves":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au matin, les mineurs respirent. Vous, à peine. Mais dans votre lumière, il y a quelque chose de nouveau : un souffle qui ne vient pas de vous."},{"qui":"narrateur","expression":"neutre","dit":"Un vieux mineur vous prend la main. « Ma grand-mère disait qu'il y a une source, dans l'Archipel, où la lumière soigne même les morts. Vous devriez la trouver. »"}],"effets":[{"flag":"heros:classe-1","reputation":{"ourvalis":3},"xp":220,"quete":{"id":"q-classe-guerisseur","etape":"etape2"}}],"choix":[],"fin":true},"epuise":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous en sauvez beaucoup. Pas tous. Le père de l'enfant s'éteint au lever du soleil, votre main sur son front."},{"qui":"narrateur","expression":"neutre","dit":"Un vieux mineur vous parle d'une source sacrée, dans l'Archipel des Brumes. « Pour la prochaine fois. Il y a toujours une prochaine fois. »"}],"effets":[{"flag":"heros:classe-1","xp":140,"quete":{"id":"q-classe-guerisseur","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-berserker-1":{"id":"cl-berserker-1","titre":"Berserker — Le sang qui chante","type":"individuel","lieu":"qarzim-porte","decor":"qarzim-porte","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"berserker"},"repetable":false,"romance":false,"quete":"q-classe-berserker","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Dans les fosses de combat, derrière la Porte des Caravanes, un vieux sang-dragon aux écailles grises défie la foule. « Qui a du feu dans les veines ? Personne ? »"}],"effets":[],"choix":[{"texte":"Descendre dans la fosse.","visible_si_bloque":false,"effets":[],"aller":"fosse"}],"fin":false},"fosse":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le vieux combattant vous regarde, renifle. « Toi. Tu as le sang. Montre-moi qu'il chante. »"}],"effets":[],"choix":[{"texte":"Encaisser ses coups sans reculer. (Vitalité, difficulté 20)","visible_si_bloque":false,"test":{"carac":"VIT","difficulte":20,"reussite":"chante","echec":"tombe"},"effets":[]},{"texte":"Frapper de toutes vos forces. (Force, difficulté 21)","visible_si_bloque":false,"test":{"carac":"FOR","difficulte":21,"reussite":"chante","echec":"tombe"},"effets":[]}],"fin":false},"chante":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le sang monte. Vos yeux brûlent. Pendant une seconde, vous voyez des ailes dans votre ombre. Le vieux sang-dragon recule, ravi. « Il chante ! »"},{"qui":"narrateur","expression":"neutre","dit":"« Va au Nid des Wyrms, dans l'Archipel. Écoute les vieux dragons. Ton sang apprendra la chanson entière. »"}],"effets":[{"flag":"heros:classe-1","xp":200,"or":50,"quete":{"id":"q-classe-berserker","etape":"etape2"}}],"choix":[],"fin":true},"tombe":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous voilà dans la poussière. La foule rit. Le vieux sang-dragon ne rit pas. « Il chante faux, mais il chante. » Il vous parle du Nid des Wyrms."}],"effets":[{"flag":"heros:classe-1","xp":120,"quete":{"id":"q-classe-berserker","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-barde-1":{"id":"cl-barde-1","titre":"Barde — La chanson perdue","type":"individuel","lieu":"qarzim-oasis","decor":"qarzim-oasis","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"barde"},"repetable":false,"romance":false,"quete":"q-classe-barde","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ziyane","expression":"neutre","dit":"« Les Dunes chantantes ? » Mère Ziyane hausse les épaules. « Les bardes de passage essaient tous de noter leur chant. Ils repartent tous fous. »"},{"qui":"narrateur","expression":"neutre","dit":"La nuit venue, vous montez sur la terrasse. Au loin, les dunes chantent. Une mélodie impossible, qui change à chaque souffle."}],"effets":[],"choix":[{"texte":"Jouer avec elles, au lieu de les noter. (Charisme, difficulté 20)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":20,"reussite":"accord","echec":"fausse"},"effets":[]}],"fin":false},"accord":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Votre instrument trouve la note. Puis une autre. Les dunes vous répondent, comme un chœur. À l'aube, vous avez trois couplets. Il en manque un : le dernier."},{"qui":"narrateur","expression":"neutre","dit":"Un vieux caravanier, en bas, a tout entendu. « Le dernier couplet, ce sont les sirènes de l'Archipel qui le chantent. Tout le monde sait ça. »"}],"effets":[{"flag":"heros:classe-1","xp":200,"quete":{"id":"q-classe-barde","etape":"etape2"}}],"choix":[],"fin":true},"fausse":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Une fausse note, et les dunes se taisent, vexées. Mais vous avez entendu assez pour savoir : il manque un couplet, que chantent les sirènes de l'Archipel."}],"effets":[{"flag":"heros:classe-1","xp":120,"quete":{"id":"q-classe-barde","etape":"etape2"}}],"choix":[],"fin":true}}},"ky-grillades":{"id":"ky-grillades","titre":"Kaya — Le concours de brochettes","type":"individuel","lieu":"qarzim-oasis","decor":"qarzim-oasis","debut":"debut","disponible_si":{"flag":"kaya-recrutee","affinite_min":{"kaya":5}},"repetable":false,"romance":false,"pnj":"kaya","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"kaya","expression":"neutre","dit":"Kaya pose deux montagnes de brochettes sur la table. « Concours ! Celui qui en mange le plus a gagné. Le perdant paie. Et ne viens pas pleurer après. »"}],"effets":[],"choix":[{"texte":"Relever le défi. (Vitalité, difficulté 19)","visible_si_bloque":false,"test":{"carac":"VIT","difficulte":19,"reussite":"gagne","echec":"perd"},"effets":[]},{"texte":"Tricher en glissant des brochettes sous la table.","visible_si_bloque":false,"effets":[{"flag":"heros:triche-brochettes"}],"aller":"triche"},{"texte":"« Je te regarde manger, ça me suffit. »","visible_si_bloque":false,"effets":[{"affinite":{"kaya":2}}],"aller":"regarde"}],"fin":false},"gagne":{"repliques":[{"qui":"kaya","expression":"surprise","dit":"Kaya fixe votre assiette vide, puis la sienne, à moitié pleine. « Impossible. Tu as un deuxième estomac. Avoue. »"},{"qui":"kaya","expression":"joie","dit":"Elle éclate de rire et vous donne une tape dans le dos à vous décrocher une épaule. « Revanche demain ! »"}],"effets":[{"affinite":{"kaya":7}}],"choix":[],"fin":true},"perd":{"repliques":[{"qui":"kaya","expression":"joie","dit":"« HA ! » Kaya lève les bras au ciel, une brochette dans chaque main. « La reine des brochettes ! Tu paies ! »"}],"effets":[{"affinite":{"kaya":5},"or":-10}],"choix":[],"fin":true},"triche":{"repliques":[{"qui":"kaya","expression":"colere","dit":"Kaya renifle. Une fois. Deux fois. Puis elle se penche sous la table. « Sérieusement ? Tu triches à un concours de brochettes ? » Elle vous jette un os à la figure… mais elle rit à moitié."}],"effets":[{"affinite":{"kaya":-2}}],"choix":[],"fin":true},"regarde":{"repliques":[{"qui":"kaya","expression":"gene","dit":"Kaya s'arrête, une brochette à mi-chemin. Ses oreilles rougissent. « Mange au lieu de dire des bêtises. »"}],"effets":[],"choix":[],"fin":true}}},"ky-hurlement":{"id":"ky-hurlement","titre":"Kaya — Le Hurlement des Ancêtres","type":"individuel","lieu":"campement-lunecroc","decor":"campement-lunecroc","debut":"debut","disponible_si":{"flag":"kaya-recrutee","affinite_palier":{"kaya":"proche"}},"repetable":false,"romance":false,"quete":"q-kaya","pnj":"sorha","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"sorha","expression":"neutre","dit":"La nuit est pleine. L'Ancienne Sorha a allumé un feu bleu au centre du campement. « Kaya veut hurler avec les ancêtres. Elle a choisi qui l'accompagnerait. » Elle vous regarde de son œil valide. « Toi. »"},{"qui":"kaya","expression":"neutre","dit":"Kaya ne plaisante pas, pour une fois. « Quand un Lunecroc hurle sur la falaise, les ancêtres répondent. Ou pas. S'ils ne répondent pas, c'est qu'on ne mérite pas encore. Moi, ils ne m'ont jamais répondu. »"}],"effets":[],"choix":[{"texte":"Hurler avec elle, de toutes vos forces.","visible_si_bloque":false,"effets":[],"aller":"hurle"},{"texte":"Lui prendre la main, en silence, pendant qu'elle hurle.","visible_si_bloque":false,"effets":[],"aller":"main"}],"fin":false},"hurle":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vos deux voix montent dans la nuit, maladroites puis justes. Et du fond du désert… quelque chose répond. Un hurlement immense, qui fait trembler le sable."}],"effets":[],"choix":[],"suite":"reponse","fin":false},"main":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Kaya hurle. Sa main serre la vôtre à vous briser les doigts. Et du fond du désert… quelque chose répond. Un hurlement immense, qui fait trembler le sable."}],"effets":[],"choix":[],"suite":"reponse","fin":false},"reponse":{"repliques":[{"qui":"kaya","expression":"tristesse","dit":"Kaya pleure sans s'en cacher. « Ils ont répondu. Ils ont répondu… » Elle s'essuie les yeux d'un revers de bras. « Je deviendrai rang S. Je reprendrai nos terres. Et tu seras là pour voir ça. C'est un ordre. »"}],"effets":[{"reputation":{"ourvalis":5},"affinite":{"kaya":10},"quete":{"id":"q-kaya","etape":"terres"}}],"choix":[],"fin":true}}},"ky-falaise":{"id":"ky-falaise","titre":"Kaya — La falaise au clair de lune","type":"individuel","lieu":"campement-lunecroc","decor":"campement-lunecroc","debut":"debut","disponible_si":{"flag":"kaya-recrutee","affinite_palier":{"kaya":"amoureuse"}},"repetable":false,"romance":true,"pnj":"kaya","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"kaya","expression":"gene","dit":"Kaya est assise au bord de la falaise, la queue battant nerveusement le rocher. « Chez nous, quand on aime quelqu'un, on le lui dit. Pas de détours. Pas de poèmes. Alors… » Elle inspire. « Je t'aime. Voilà. C'est dit. »"}],"effets":[],"choix":[{"texte":"« Moi aussi, Kaya. Sans détour. »","visible_si_bloque":false,"effets":[{"affinite":{"kaya":6}}],"aller":"oui"},{"texte":"L'embrasser pour toute réponse.","visible_si_bloque":false,"effets":[{"affinite":{"kaya":6}}],"aller":"oui"}],"fin":false},"oui":{"repliques":[{"qui":"kaya","expression":"joie","dit":"Elle rit, un rire qui finit en hurlement de joie lancé à la lune. Puis elle se blottit contre vous, et la nuit du désert devient soudain très chaude…"},{"qui":"narrateur","expression":"neutre","dit":"(Fondu au noir.)"}],"effets":[],"choix":[],"fin":true}}},"nd-marchandage":{"id":"nd-marchandage","titre":"Nadja — Leçon de marchandage","type":"individuel","lieu":"qarzim-bazar","decor":"qarzim-bazar","debut":"debut","disponible_si":{"flag":"nadja-rencontree"},"repetable":false,"romance":false,"pnj":"nadja","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Nadja vous entraîne devant un étal de tapis. « Leçon numéro un : on ne paie jamais le premier prix. Montre-moi ce que tu vaux. »"}],"effets":[],"choix":[{"texte":"Marchander avec aplomb. (Charisme, difficulté 18)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":18,"reussite":"bien","echec":"rate"},"effets":[]},{"texte":"Laisser Nadja faire, et prendre des notes.","visible_si_bloque":false,"effets":[{"affinite":{"nadja":3}}],"aller":"notes"},{"texte":"« Ce marchand a l'air pauvre. Payons le prix qu'il demande. »","visible_si_bloque":false,"effets":[{"affinite":{"nadja":1},"or":-15}],"aller":"genereux"}],"fin":false},"bien":{"repliques":[{"qui":"nadja","expression":"surprise","dit":"Le marchand finit par vous offrir le thé ET le tapis. Nadja vous dévisage. « …Tu as déjà fait ça. Avoue. »"}],"effets":[{"affinite":{"nadja":6},"or":30}],"choix":[],"fin":true},"rate":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Vous repartez avec un tapis hors de prix et un sourire de vainqueur. Nadja se masse les tempes. « On reprendra la leçon. Depuis le début. »"}],"effets":[{"affinite":{"nadja":3},"or":-20}],"choix":[],"fin":true},"notes":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"En trois phrases, Nadja divise le prix par quatre. « Tu vois ? Le secret, c'est de toujours avoir l'air de pouvoir partir. » Elle vous fait un clin d'œil. « Avec les gens aussi. »"}],"effets":[],"choix":[],"fin":true},"genereux":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Nadja vous regarde comme si vous veniez de jeter de l'or dans un puits. Puis, plus doucement : « …Tu es bizarre. Ça me plaît, bizarrement. »"}],"effets":[],"choix":[],"fin":true}}},"nd-livre":{"id":"nd-livre","titre":"Nadja — Le Grand Livre rouge","type":"individuel","lieu":"qarzim-palais","decor":"qarzim-palais","debut":"debut","disponible_si":{"flag":"nadja-rencontree","affinite_palier":{"nadja":"proche"}},"repetable":false,"romance":false,"quete":"q-nadja","pnj":"nadja","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Minuit, au pied du Palais. Nadja a troqué ses voiles contre une tenue noire. « Ma dette est écrite dans le Grand Livre rouge, au dernier étage. Avec celles de la moitié de Qarzim, et le nom de tous les acheteurs de cristaux. Je veux une copie. Tu m'aides ? »"}],"effets":[],"choix":[{"texte":"Grimper par les terrasses. (Agilité, difficulté 21)","visible_si_bloque":false,"test":{"carac":"AGI","difficulte":21,"reussite":"copie","echec":"alerte"},"effets":[]},{"texte":"Faire diversion pendant qu'elle entre. (Charisme, difficulté 20)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":20,"reussite":"copie","echec":"alerte"},"effets":[]}],"fin":false},"copie":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le Grand Livre est un registre de cuir rouge, épais comme un tronc. Nadja recopie à toute vitesse, à la lueur d'un cristal."},{"qui":"nadja","expression":"surprise","dit":"Elle s'arrête sur une page. « Ces cristaux… ils partent vers le nord. Des caisses entières. Payées en or noir, par un acheteur qui signe d'une rune violette. » Elle pâlit. « La Concorde vend aux Cendres. »"}],"effets":[{"flag":"concorde-vend-aux-cendres","affinite":{"nadja":10},"xp":120,"objet":"grand-livre-rouge","quete":{"id":"q-nadja","etape":"acheteurs"}}],"choix":[],"suite":"fin","fin":false},"alerte":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Une cloche sonne. Des gardes ! Vous sautez de terrasse en terrasse, Nadja serrant contre elle les quelques pages qu'elle a pu arracher."},{"qui":"nadja","expression":"neutre","dit":"Dans une ruelle, à bout de souffle, elle déplie les pages. « C'est peu… mais c'est assez. Des caisses de cristaux vers le nord. Signées d'une rune violette. »"}],"effets":[{"flag":"concorde-vend-aux-cendres","reputation":{"concorde":-5},"affinite":{"nadja":7},"objet":"grand-livre-rouge","quete":{"id":"q-nadja","etape":"acheteurs"}}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"« Merci. » Nadja range les pages contre son cœur. « Personne n'avait jamais pris de risque pour moi. Personne. » Elle détourne les yeux. « Je n'aime pas avoir des dettes. Celle-là, je la garderai. »"}],"effets":[],"choix":[],"fin":true}}},"nd-terrasse":{"id":"nd-terrasse","titre":"Nadja — Les comptes d'une nuit","type":"individuel","lieu":"qarzim-oasis","decor":"qarzim-oasis","debut":"debut","disponible_si":{"flag":"nadja-rencontree","affinite_palier":{"nadja":"amoureuse"}},"repetable":false,"romance":true,"pnj":"nadja","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Sur la terrasse de l'Oasis, Nadja a sorti son carnet. Elle ne compte pas : elle dessine. Votre visage."},{"qui":"nadja","expression":"gene","dit":"Elle referme le carnet trop vite. « Ne dis rien. J'ai calculé tous les risques de cette… chose entre nous. Ils sont énormes. » Elle soupire. « Et je m'en fiche. C'est nouveau. »"}],"effets":[],"choix":[{"texte":"« Alors prenons le risque. Ensemble. »","visible_si_bloque":false,"effets":[{"affinite":{"nadja":6}}],"aller":"oui"}],"fin":false},"oui":{"repliques":[{"qui":"nadja","expression":"joie","dit":"Elle sourit, pour de vrai, sans calcul. Les voiles de la terrasse ondulent dans la brise du soir, et le carnet tombe, oublié, sur les dalles…"},{"qui":"narrateur","expression":"neutre","dit":"(Fondu au noir.)"}],"effets":[],"choix":[],"fin":true}}},"sr-contes":{"id":"sr-contes","titre":"Séraphine — Les contes de l'autre monde","type":"individuel","lieu":"qarzim-residence","decor":"qarzim-residence","debut":"debut","disponible_si":{"flag":"seraphine-recrutee"},"repetable":false,"romance":false,"pnj":"seraphine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"Séraphine vous attend dans le jardin de la Résidence, pieds nus dans l'herbe, un carnet sur les genoux. « Raconte-moi ton monde. Pas les guerres. Les petites choses. Ce que vous mangiez le matin. Les histoires qu'on racontait aux enfants. »"},{"qui":"seraphine","expression":"neutre","dit":"Elle hésite. « Toi, tu as eu une autre vie, avant. Tu t'en souviens ? »","si":{"origine":"reincarne"}}],"effets":[],"choix":[{"texte":"Lui raconter un conte de votre enfance.","visible_si_bloque":false,"effets":[{"affinite":{"seraphine":6}}],"aller":"conte"},{"texte":"Lui décrire une ville de votre monde, avec ses lumières qui ne s'éteignent jamais.","visible_si_bloque":false,"effets":[{"affinite":{"seraphine":5}}],"aller":"ville"},{"texte":"« Ce n'est pas si intéressant, tu sais. »","visible_si_bloque":false,"effets":[{"affinite":{"seraphine":-1}}],"aller":"decue"}],"fin":false},"conte":{"repliques":[{"qui":"seraphine","expression":"joie","dit":"Elle note tout, les yeux brillants, et vous fait répéter la fin trois fois. « Il faut que je l'écrive avant de l'oublier. Un jour, je ferai un livre. « Contes de l'autre côté du Voile ». »"}],"effets":[],"choix":[],"fin":true},"ville":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"« Des lumières partout, la nuit ? Sans magie ? » Elle reste silencieuse un long moment. « Chez vous, personne n'a besoin d'Appelés. C'est peut-être ça, un monde heureux. »"}],"effets":[],"choix":[],"fin":true},"decue":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"Elle referme son carnet. « Tout est intéressant, quand on ne l'a jamais vu. » Elle sourit poliment, mais quelque chose s'est éteint."}],"effets":[],"choix":[],"fin":true}}},"sr-anneau":{"id":"sr-anneau","titre":"Séraphine — L'anneau d'Aldric","type":"individuel","lieu":"qarzim-bazar","decor":"qarzim-bazar","debut":"debut","disponible_si":{"flag":"seraphine-recrutee","affinite_palier":{"seraphine":"proche"}},"repetable":false,"romance":false,"quete":"q-seraphine","pnj":"seraphine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"Séraphine vous entraîne au fond du Bazar, chez un prêteur sur gages. Elle tremble. « Un marchand m'a écrit. Il a vu passer un anneau gravé d'un griffon. Celui de mon frère. »"},{"qui":"narrateur","expression":"neutre","dit":"Le prêteur sort l'anneau d'un coffret. Un griffon d'argent, une pierre bleue. Et, à l'intérieur, une inscription : « À A., de S. — reviens-moi »."},{"qui":"seraphine","expression":"tristesse","dit":"« C'est moi qui le lui ai offert. » Sa voix se brise. « Il l'avait au doigt le jour où il a disparu. »"}],"effets":[],"choix":[{"texte":"Demander au prêteur d'où il vient. (Charisme, difficulté 20)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":20,"reussite":"piste","echec":"rachat"},"effets":[]},{"texte":"Racheter l'anneau pour Séraphine. (100 or)","si":{"or_min":100},"visible_si_bloque":false,"effets":[{"affinite":{"seraphine":4},"or":-100}],"aller":"piste"}],"fin":false},"piste":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le prêteur finit par parler : l'anneau a été vendu par un marchand du nord, qui l'avait lui-même échangé contre de l'eau… à un homme en armure noire, sur le Mur d'Aube, il y a deux ans."},{"qui":"seraphine","expression":"neutre","dit":"« Deux ans. » Séraphine serre l'anneau. « Il y a deux ans, il était vivant. » Elle vous regarde, et pour la première fois depuis longtemps, elle sourit à travers ses larmes. « Merci. »"}],"effets":[{"flag":"aldric-vivant-indice","affinite":{"seraphine":10},"xp":100,"quete":{"id":"q-seraphine","etape":"rumeurs"}}],"choix":[],"fin":true},"rachat":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le prêteur ne dira rien de plus. Mais Séraphine repart avec l'anneau au doigt."},{"qui":"seraphine","expression":"neutre","dit":"« Il est vivant quelque part. Je le sens. » Elle serre votre main. « Tu m'aideras à le retrouver ? »"}],"effets":[{"affinite":{"seraphine":8},"quete":{"id":"q-seraphine","etape":"rumeurs"}}],"choix":[],"fin":true}}},"sr-jardin":{"id":"sr-jardin","titre":"Séraphine — Le jardin de nuit","type":"individuel","lieu":"qarzim-residence","decor":"qarzim-residence","debut":"debut","disponible_si":{"flag":"seraphine-recrutee","affinite_palier":{"seraphine":"amoureuse"}},"repetable":false,"romance":true,"pnj":"seraphine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"seraphine","expression":"gene","dit":"Dans le jardin, sous les palmiers, Séraphine a fait apporter deux coupes d'eau fraîche et un plateau de dattes. « Pas de garde. Pas de protocole. Ce soir, je ne suis pas princesse. » Elle rougit. « Je suis juste… moi. Avec toi. »"}],"effets":[],"choix":[{"texte":"« Alors ce soir, je ne suis pas un Appelé. Juste moi. »","visible_si_bloque":false,"effets":[{"affinite":{"seraphine":6}}],"aller":"oui"}],"fin":false},"oui":{"repliques":[{"qui":"seraphine","expression":"joie","dit":"Elle rit, se lève, et vous tend la main pour une danse sans musique, pieds nus dans l'herbe. Au loin, Qarzim s'endort, et les étoiles du désert veillent sur vous…"},{"qui":"narrateur","expression":"neutre","dit":"(Fondu au noir.)"}],"effets":[],"choix":[],"fin":true}}},"av-archives":{"id":"av-archives","titre":"Aveline — La lettre de Valgrane","type":"individuel","lieu":"qarzim-residence","decor":"qarzim-residence","debut":"debut","disponible_si":{"flag":"seraphine-recrutee","affinite_min":{"aveline":45},"quete_etape":{"q-aveline":"archives"}},"repetable":false,"romance":false,"quete":"q-aveline","pnj":"aveline","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Aveline vous attend dans la bibliothèque de la Résidence, une lettre jaunie entre les mains. « Séraphine l'a fait sortir des archives royales. En secret. Elle a risqué gros. »"},{"qui":"aveline","expression":"colere","dit":"« C'est l'ordre de repli de Valgrane. Signé de mon père, oui. Mais regarde : le sceau du bas. Ce n'est pas celui de la Couronne. C'est celui de l'Ordre de la Lumière. »"},{"qui":"aveline","expression":"neutre","dit":"« Mon père n'a pas ouvert les portes. On lui a ordonné de se replier. L'Ordre a donné l'ordre… puis l'a laissé accuser. »"}],"effets":[],"choix":[{"texte":"« Nous irons jusqu'au bout. Même s'il faut regarder l'Ordre en face. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":8}}],"aller":"fin"},{"texte":"« Prends ton temps. On ne renverse pas l'Ordre sur une lettre. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":4}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Elle replie la lettre et vous la confie. « Garde-la. Si on me fouille, on ne la trouvera pas. » Elle vous regarde. « Je te fais confiance. Plus qu'à moi-même. »"}],"effets":[{"flag":"ordre-valgrane-indice","xp":100,"objet":"lettre-valgrane","quete":{"id":"q-aveline","etape":"verite"}}],"choix":[],"fin":true}}},"ch2-depart":{"id":"ch2-depart","titre":"Le départ","type":"groupe","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"flag":"chapitre-1-fini","pas_flag":"ch2-depart-fait","date_min":{"annee":1015,"mois":1,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch2-routes","pnj":"seraphine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Germinal 1015. Trois ans ont passé depuis l'Appel. Les cicatrices de la Nuit des Lanternes se sont refermées ; pas celles des souvenirs."},{"qui":"seraphine","expression":"neutre","dit":"La princesse Séraphine [[t'attend||vous attend]] dans la salle des cartes, en tenue de voyage, les cheveux noués comme un soldat. « Enfin ! Mon père m'envoie à Qarzim. Officiellement : signer un traité de commerce avec la Concorde. »"},{"qui":"seraphine","expression":"neutre","dit":"« Officieusement : la Concorde vend des cristaux d'éther à tout le monde… y compris, dit-on, à des gens qui portent des sceaux violets. » Elle pose la main sur la carte du sud. « J'ai demandé [[un Appelé||des Appelés]] pour m'escorter. Je veux [[toi||vous]]. »"},{"qui":"aveline","expression":"neutre","dit":"Aveline se tient près de la porte, bras croisés. « Ordre du roi : j'accompagne la princesse. Et… [[toi||vous]] aussi, apparemment. » Elle ne cache pas tout à fait son sourire."},{"qui":"kaya","expression":"neutre","dit":"La porte s'ouvre à la volée. Kaya, sac au dos, oreilles dressées : « Qarzim ? Vous allez dans le désert sans guide ? Vous allez mourir de soif avant midi. J'en suis ! »"}],"effets":[],"choix":[{"texte":"« Une mission diplomatique ? Nous serons des modèles de politesse. »","visible_si_bloque":false,"effets":[{"reputation":{"couronne":3},"affinite":{"seraphine":3}}],"aller":"politesse"},{"texte":"« Si la Concorde aide les Cendres, je veux le savoir. Le traité, je m'en moque. »","visible_si_bloque":false,"effets":[{"flag":"enquete-concorde","affinite":{"seraphine":4,"aveline":2}}],"aller":"enquete"},{"texte":"« Kaya, c'est chez toi, là-bas ? Tu seras notre guide. »","visible_si_bloque":false,"effets":[{"affinite":{"kaya":5}}],"aller":"kaya"}],"fin":false},"politesse":{"repliques":[{"qui":"seraphine","expression":"joie","dit":"Séraphine éclate de rire. « Des modèles de politesse. Vous. Je garde la phrase pour la raconter à mon père. »"}],"effets":[],"choix":[],"suite":"preparatifs","fin":false},"enquete":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"« Exactement ce que je voulais entendre. » Elle baisse la voix. « Et pas un mot à la cour. La moitié des nobles a des parts dans les caravanes de la Concorde. »"}],"effets":[],"choix":[],"suite":"preparatifs","fin":false},"kaya":{"repliques":[{"qui":"kaya","expression":"joie","dit":"Kaya bombe le torse. « Chez moi, c'est le désert entier. Enfin… c'était. » Son sourire vacille une seconde. « La Concorde nous a pris nos terres. Mais je connais chaque dune. »"}],"effets":[],"choix":[],"suite":"preparatifs","fin":false},"preparatifs":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"Dame Rowena vous a fait parvenir un mot : « La Guilde a un comptoir à Qarzim. Montrez-vous là-bas, l'intendant Ibrek vous trouvera du travail. Et ramenez la princesse entière. »"},{"qui":"narrateur","expression":"neutre","dit":"Trois jours plus tard, la caravane de la princesse quitte Lysmont par la porte du sud. Devant vous, la Route des Caravanes, et au bout, la Marche des Sables."}],"effets":[{"flag":["ch2-depart-fait","seraphine-recrutee","kaya-recrutee"],"quete":{"id":"q-ch2-routes","etape":"caravane"},"recruter":"seraphine","journal":"Germinal 1015 : {groupe} partent pour Qarzim avec la princesse Séraphine, Aveline et Kaya."},{"recruter":"kaya"}],"choix":[],"fin":true}}},"ch2-caravane":{"id":"ch2-caravane","titre":"La Route des Caravanes","type":"groupe","lieu":"route-des-caravanes","decor":"route-des-caravanes","debut":"debut","disponible_si":{"quete_etape":{"q-ch2-routes":"caravane"}},"repetable":false,"romance":false,"quete":"q-ch2-routes","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Dix jours de route. L'herbe d'Aubeclaire devient poussière, puis sable. Le soleil tape comme un marteau sur une enclume."},{"qui":"nadja","expression":"neutre","dit":"La caravane appartient à une courtière : une femme en voiles ocre, un carnet à la main, qui compte les tonneaux d'eau à voix haute. « Nadja Kesh. Chaque gorgée que vous buvez est notée. Princesse comprise. »"},{"qui":"kaya","expression":"neutre","dit":"Kaya s'arrête net, nez au vent. « Ça sent le cuir et le sang. Des gens nous attendent derrière ces rochers. »"}],"effets":[],"choix":[{"texte":"Préparer une contre-embuscade. (Esprit, difficulté 20)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":20,"reussite":"contre","echec":"surpris"},"effets":[]},{"texte":"Continuer et laisser venir : la caravane est bien gardée.","visible_si_bloque":false,"effets":[],"aller":"surpris"}],"fin":false},"contre":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous contournez les rochers. Les pillards, le dos tourné, guettent la caravane… et ne vous voient pas venir."}],"effets":[{"xp":40}],"choix":[],"suite":"combat","fin":false},"surpris":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Des cris. Des flèches. Des silhouettes au chèche turquoise dévalent la dune, cimeterres au clair."}],"effets":[],"choix":[],"suite":"combat","fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"caravane-pillards","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le dernier pillard lâche son arme. Un jeune, à peine seize ans, qui tremble sous son chèche."},{"qui":"nadja","expression":"neutre","dit":"Nadja enjambe un corps sans le regarder et rouvre son carnet. « Deux chameaux blessés, un tonneau percé. » Elle lève les yeux vers vous. « Et zéro mort de notre côté. Pas mal, pour des étrangers. »"}],"effets":[{"reputation":{"concorde":3},"affinite":{"nadja":3}}],"choix":[],"suite":"prisonnier","fin":false},"defaite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous reprenez connaissance sous une toile tendue. Les gardes de la caravane ont repoussé les pillards à grand-peine."},{"qui":"nadja","expression":"neutre","dit":"« Trois chameaux, deux tonneaux et ma réputation. » Nadja soupire. « La prochaine fois, laissez-moi négocier. »"}],"effets":[],"choix":[],"suite":"prisonnier","fin":false},"prisonnier":{"repliques":[{"qui":"kaya","expression":"neutre","dit":"Kaya tient le jeune pillard par le col. « Il dit qu'on les a payés. Pas pour voler : pour retarder la princesse. »"}],"effets":[],"choix":[{"texte":"L'emmener à Qarzim : la garde de la ville le fera parler.","visible_si_bloque":false,"effets":[{"flag":"prisonnier-pillard"}],"aller":"arrivee"},{"texte":"Le laisser partir avec de l'eau. Ce n'est qu'un gamin.","visible_si_bloque":false,"effets":[{"flag":["prisonnier-pillard","pillard-epargne"],"affinite":{"kaya":2,"seraphine":3}}],"aller":"arrivee"}],"fin":false},"arrivee":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au coucher du soleil, Qarzim apparaît : des coupoles bleues, des tours de terre ocre, et au-dessus de la ville, une lueur violette qui ne vient pas du ciel."},{"qui":"nadja","expression":"neutre","dit":"« Les cristaux d'éther. » Nadja range son carnet. « Toute la ville en brille. Si vous avez besoin de quelque chose à Qarzim — n'importe quoi — demandez Nadja Kesh, à la Porte des Caravanes. Pour un prix honnête. » Elle sourit. « Enfin, presque. »"}],"effets":[{"flag":["sables-ouverts","nadja-rencontree"],"xp":120,"quete":{"id":"q-ch2-routes","etape":"palais"},"recruter":"nadja","journal":"{groupe} arrivent à Qarzim avec la caravane de Nadja Kesh, après une embuscade de pillards."}],"choix":[],"fin":true}}},"ch2-palais":{"id":"ch2-palais","titre":"Le Prévôt de la Concorde","type":"groupe","lieu":"qarzim-palais","decor":"qarzim-palais","debut":"debut","disponible_si":{"quete_etape":{"q-ch2-routes":"palais"}},"repetable":false,"romance":false,"quete":"q-ch2-routes","pnj":"hassad","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le Palais de la Concorde est un rêve de marbre et de cristal. Des fontaines coulent dans des vasques violettes. Ici, même l'air sent l'argent."},{"qui":"hassad","expression":"neutre","dit":"Le Prévôt Hassad s'incline juste assez. « Princesse. Et les fameux Appelés. » Ses bagues-cristaux scintillent. « La Concorde est honorée. Elle serait plus honorée encore si le traité ne parlait pas des mines. »"},{"qui":"vashti","expression":"neutre","dit":"Une conseillère à l'éventail sourit derrière lui. « Les mines sont une affaire de Qarzim, Altesse. Les loups du désert les réclament, mais les loups réclament toujours. »"},{"qui":"kaya","expression":"colere","dit":"Kaya serre les poings. Ses oreilles se couchent en arrière."}],"effets":[],"choix":[],"suite":"question","fin":false},"question":{"parole_a":{"regle":{"race":["ourvalis","vulpin","demi-demon","sang-dragon"]},"question":{"qui":"hassad","expression":"neutre","dit":"Le Prévôt se tourne vers {nom}. « Et vous, {pseudo} ? Les Appelés sont-ils venus défendre les traités… ou les tribus ? »"},"reponses":[{"texte":"« Je suis ourvalis, Prévôt. Les « loups du désert », c'est moi. Choisissez mieux vos mots. »","si":{"race":"ourvalis"},"effets":[{"reputation":{"ourvalis":8,"concorde":-5},"affinite":{"kaya":6}}],"aller":"reponse"},{"texte":"« Les vulpins commercent avec vous depuis des siècles. Ne me faites pas croire que vous ignorez qui vit sur ces terres. »","si":{"race":"vulpin"},"effets":[{"reputation":{"ourvalis":4,"concorde":-2},"affinite":{"nadja":2}}],"aller":"reponse"},{"texte":"« On m'a souvent traité de monstre. Je sais reconnaître quand on parle des autres comme ça. »","si":{"race":["demi-demon","sang-dragon"]},"effets":[{"affinite":{"kaya":4,"seraphine":2}}],"aller":"reponse"},{"texte":"« Nous défendons la princesse. Le reste dépendra de ce que nous verrons. »","effets":[{"affinite":{"seraphine":3}}],"aller":"reponse"},{"texte":"« Les tribus vivaient ici avant vos mines. Ça compte, non ? »","effets":[{"reputation":{"ourvalis":5,"concorde":-4},"affinite":{"kaya":4}}],"aller":"reponse"},{"texte":"« Nous sommes là pour le traité. Et pour le buffet. »","effets":[{"affinite":{"seraphine":2}}],"aller":"reponse"}]},"repliques":[],"effets":[],"choix":[],"fin":false},"reponse":{"repliques":[{"qui":"hassad","expression":"neutre","dit":"Le Prévôt sourit sans que ses yeux bougent. « Intéressant. » Il fait un signe : un serviteur vous tend à chacun un petit cristal violet, serti d'argent. « Un présent de la Concorde. Que la lumière de l'éther éclaire vos chemins. »"},{"qui":"seraphine","expression":"neutre","dit":"Séraphine murmure sans remuer les lèvres : « Ne le portez pas sur vous. J'ai un mauvais pressentiment. »"}],"effets":[],"choix":[{"texte":"Accepter le cristal avec un grand sourire.","visible_si_bloque":false,"effets":[{"flag":"cadeau-hassad","reputation":{"concorde":5},"objet":"cristal-ether"}],"aller":"fin"},{"texte":"Refuser poliment : « Nous ne pouvons accepter un tel présent. »","visible_si_bloque":false,"effets":[{"reputation":{"concorde":-3},"affinite":{"seraphine":3,"kaya":2}}],"aller":"fin"},{"texte":"Accepter, et l'examiner discrètement. (Intelligence, difficulté 20)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":20,"reussite":"examen","echec":"fin"},"effets":[]}],"fin":false},"examen":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Dans la lumière, le cristal palpite. Lentement. Comme une veine. À l'intérieur, une minuscule déchirure violette se referme et se rouvre."}],"effets":[{"flag":["cristal-palpite","cadeau-hassad"],"xp":50,"objet":"cristal-ether"}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les négociations dureront des mois : la Concorde est patiente, et sa patience coûte cher. La princesse s'installe à la Résidence d'Aubeclaire."},{"qui":"seraphine","expression":"neutre","dit":"« Le grand banquet de la Résidence aura lieu le 10 Ardent de l'an prochain. Tout Qarzim y sera. » Elle soupire. « D'ici là, faites-vous connaître : la Guilde, les tribus, le Bazar. J'ai besoin d'yeux partout. »"}],"effets":[{"quete":{"id":"q-ch2-routes","etape":"complot"},"journal":"{groupe} rencontrent le Prévôt Hassad. La Concorde offre des cristaux d'éther en cadeau."}],"choix":[],"fin":true}}},"ch2-complot":{"id":"ch2-complot","titre":"Le banquet","type":"groupe","lieu":"qarzim-residence","decor":"qarzim-residence","debut":"debut","disponible_si":{"quete_etape":{"q-ch2-routes":"complot"},"date_min":{"annee":1016,"mois":6,"jour":10}},"repetable":false,"romance":false,"quete":"q-ch2-routes","pnj":"seraphine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"10 Ardent 1016. La Résidence d'Aubeclaire brille de mille lanternes. Musiciens, plats d'argent, marchands de la Concorde en soie : tout Qarzim est là."},{"qui":"seraphine","expression":"neutre","dit":"Séraphine, en robe blanche et or, sourit à tout le monde. Mais sous la table, elle [[te||vous]] glisse un mot : « Vashti n'a pas quitté mon verre des yeux. »"},{"qui":"vashti","expression":"neutre","dit":"La conseillère Vashti lève sa coupe. « À l'amitié entre Aubeclaire et la Concorde ! » Les serviteurs remplissent les verres de la princesse."}],"effets":[],"choix":[],"suite":"poison","fin":false},"poison":{"parole_a":{"regle":{"classe":["alchimiste","guerisseur","ombre"]},"question":{"qui":"seraphine","expression":"neutre","dit":"Séraphine porte la coupe à ses lèvres, puis s'arrête et la tend discrètement à {nom}. « {pseudo}… Il y a quelque chose de bizarre avec ce vin, non ? »"},"reponses":[{"texte":"« Ne bois pas ! L'odeur d'amande… c'est du venin de scorpion bleu. »","si":{"classe":"alchimiste"},"effets":[{"flag":"poison-decouvert","affinite":{"seraphine":6}}],"aller":"assassins"},{"texte":"« Je sens une fièvre dans ce liquide. Comme une malédiction. Pose ça. »","si":{"classe":"guerisseur"},"effets":[{"flag":"poison-decouvert","affinite":{"seraphine":6}}],"aller":"assassins"},{"texte":"« Le serviteur qui t'a servie vient de disparaître. Mauvais signe. »","si":{"classe":"ombre"},"effets":[{"flag":"poison-decouvert","affinite":{"seraphine":6}}],"aller":"assassins"},{"texte":"« Dans le doute… » (lui prendre la coupe et la renverser sur la nappe)","effets":[{"flag":"poison-decouvert","affinite":{"seraphine":4}}],"aller":"assassins"},{"texte":"« Il est très bon. Pourquoi ? »","effets":[{"affinite":{"seraphine":1}}],"aller":"assassins"},{"texte":"« Laisse-moi goûter d'abord. » (héroïque, mais imprudent)","effets":[{"affinite":{"seraphine":5}}],"aller":"assassins"}]},"repliques":[],"effets":[],"choix":[],"fin":false},"assassins":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La coupe renversée fume en rongeant la nappe. Un silence glacé tombe sur la salle."},{"qui":"narrateur","expression":"neutre","dit":"Puis les serviteurs lâchent leurs plateaux. Sous les tuniques, des poignards courbes. Des voiles noirs. La Main de Sable."},{"qui":"aveline","expression":"colere","dit":"« Protégez la princesse ! » Aveline renverse une table pour faire barrage."}],"effets":[],"choix":[],"combat":{"rencontre":"assassins-banquet","victoire":"poursuite","defaite":"blessee"},"fin":false},"blessee":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un poignard a effleuré le bras de Séraphine. La garde de la Résidence repousse les assassins, qui s'enfuient par les toits."}],"effets":[{"flag":"seraphine-blessee","affinite":{"seraphine":-2}}],"choix":[],"suite":"poursuite","fin":false},"poursuite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Une silhouette voilée de noir vous observe depuis la coupole d'en face. Elle s'incline, moqueuse, et s'éloigne de toit en toit."},{"qui":"kaya","expression":"neutre","dit":"« C'est le chef ! Je le sens d'ici. » Kaya bondit déjà vers la fenêtre."}],"effets":[],"choix":[{"texte":"Le poursuivre sur les toits de Qarzim.","visible_si_bloque":false,"effets":[],"aller":"toits"},{"texte":"Rester auprès de la princesse : c'est peut-être une diversion.","visible_si_bloque":false,"effets":[{"affinite":{"seraphine":4,"aveline":3}}],"aller":"diversion"}],"fin":false},"diversion":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Bien vu : un deuxième groupe d'assassins surgit des cuisines. Vous les attendiez."}],"effets":[],"choix":[],"suite":"toits","fin":false},"toits":{"repliques":[{"qui":"kezir","expression":"neutre","dit":"Sur la plus haute terrasse, l'homme voilé vous attend, deux lames à la main. « Kezir. On m'a payé pour une princesse. Les Appelés seront un bonus. »"}],"effets":[],"choix":[],"combat":{"rencontre":"kezir-toits","victoire":"preuve","defaite":"fuite-kezir"},"fin":false},"fuite-kezir":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Kezir vous laisse au sol et disparaît dans la nuit. Mais dans sa fuite, il a perdu quelque chose."}],"effets":[],"choix":[],"suite":"preuve","fin":false},"preuve":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Sur la terrasse, un insigne de bronze : une main tenant un grain de sable. Et, enroulée autour, une lettre de paiement… scellée du sceau personnel de la conseillère Vashti Orren."},{"qui":"narrateur","expression":"neutre","dit":"Au dos de la lettre, une rune violette griffonnée à la hâte. La même que sur le sceau cendré de la Crypte.","si":{"flag":"sceau-trouve"}}],"effets":[{"xp":150,"objet":"insigne-main-de-sable"}],"choix":[{"texte":"Dénoncer Vashti devant le Conseil de la Concorde, preuve à l'appui.","visible_si_bloque":false,"effets":[{"flag":"vashti-denoncee","reputation":{"concorde":-10,"couronne":10},"affinite":{"seraphine":4}}],"aller":"denonce"},{"texte":"Donner la lettre à Nadja : elle saura quoi en faire, sans bruit.","visible_si_bloque":false,"effets":[{"flag":"preuve-nadja","affinite":{"nadja":8}}],"aller":"nadja"},{"texte":"Aller voir le Prévôt Hassad en privé : qu'il nous doive une faveur.","visible_si_bloque":false,"effets":[{"flag":"hassad-redevable","reputation":{"concorde":8}}],"aller":"hassad"}],"fin":false},"denonce":{"repliques":[{"qui":"vashti","expression":"neutre","dit":"Devant le Conseil, Vashti pâlit, puis rit. « Une lettre ? N'importe qui peut voler un sceau. » Mais personne ne rit avec elle. Elle est arrêtée le soir même… et retrouvée morte dans sa cellule à l'aube."},{"qui":"seraphine","expression":"neutre","dit":"« Quelqu'un ne voulait pas qu'elle parle. » Séraphine fixe la fenêtre. « Quelqu'un de plus haut. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"nadja":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Nadja lit la lettre deux fois, puis la plie avec un soin infini. « Vashti me doit maintenant beaucoup plus que je ne lui dois. » Pour la première fois, son sourire est vrai. « Merci. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"hassad":{"repliques":[{"qui":"hassad","expression":"neutre","dit":"Le Prévôt brûle la lettre à la flamme d'une bougie sans la lire jusqu'au bout. « La Concorde n'oublie jamais une dette. » Le lendemain, Vashti a quitté Qarzim. Personne ne sait où."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"Plus tard, sur la terrasse de la Résidence, Séraphine tient son verre d'eau à deux mains. « Merci. Vraiment. » Elle hésite. « Le Grand Bazar ouvre le premier jour de Brumaire. Les gens y parlent. On y apprendra peut-être qui a payé Vashti. »"}],"effets":[{"quete":{"id":"q-ch2-routes","etape":"bazar"},"journal":"10 Ardent 1016 : tentative d'assassinat contre la princesse Séraphine à Qarzim. La Main de Sable était payée par la conseillère Vashti."}],"choix":[],"fin":true}}},"ch2-bazar":{"id":"ch2-bazar","titre":"Le Grand Bazar","type":"groupe","lieu":"qarzim-bazar","decor":"qarzim-bazar","debut":"debut","disponible_si":{"quete_etape":{"q-ch2-routes":"bazar"},"date_min":{"annee":1016,"mois":7,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch2-routes","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"1er Brumaire 1016. Le Grand Bazar de Qarzim s'éveille : des caravanes de tout le continent, des tapis volants (qui ne volent pas), des épices en montagnes, des cris dans dix langues."},{"qui":"narrateur","expression":"neutre","dit":"Et partout, des cristaux d'éther : en colliers, en lampes, en poudre « contre la fatigue ». Les marchands de la Concorde les vendent par caisses entières."},{"qui":"faelis","expression":"neutre","dit":"Sous une tente verte, une elfe aux cheveux d'argent vend des herbes. Elle vous fixe longuement. « Des Appelés. Ici. Avec ça plein les poches. » Elle désigne les cristaux d'un geste dégoûté."}],"effets":[],"choix":[{"texte":"« Vous savez quelque chose sur ces cristaux ? »","visible_si_bloque":false,"effets":[],"aller":"faelis"},{"texte":"Montrer le sceau cendré à l'elfe.","si":{"objet":"sceau-cendre"},"visible_si_bloque":false,"effets":[],"aller":"sceau"}],"fin":false},"sceau":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À l'instant où le sceau sort du sac, tous les cristaux de la tente se mettent à vibrer. Un bourdonnement monte, aigu, et des lueurs violettes dansent sur les toiles."},{"qui":"faelis","expression":"surprise","dit":"L'elfe recule, livide. « Rangez ça. Tout de suite. » Elle respire mieux quand le sceau a disparu. « Ils se reconnaissent. Ils viennent du même endroit. »"}],"effets":[{"flag":"cristaux-resonnent","xp":60}],"choix":[],"suite":"faelis","fin":false},"faelis":{"repliques":[{"qui":"faelis","expression":"neutre","dit":"« Je m'appelle Faelis. Je viens de Sylvenoire. » Elle baisse la voix. « Chez nous, on enseigne que le Voile n'est pas une idée. C'est une chose. Une peau entre les mondes. Et une peau qu'on gratte… finit par saigner. »"},{"qui":"faelis","expression":"neutre","dit":"« Ces cristaux ne poussent pas dans la roche. Ce sont des éclats. Des éclats du Voile, tombés lors de la Déchirure. Chaque cristal qu'on arrache affaiblit ce qui reste. »"}],"effets":[],"choix":[{"texte":"« Comment pouvez-vous en être sûre ? » (Intelligence, difficulté 21)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":21,"reussite":"preuve","echec":"doute"},"effets":[]},{"texte":"« Si c'est vrai, la Concorde doit l'apprendre. »","visible_si_bloque":false,"effets":[],"aller":"concorde"}],"fin":false},"preuve":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Faelis déroule un vieux parchemin : un dessin de cristal, des runes elfiques, et une phrase traduite à la main. « Ce que nous avons déchiré, la terre l'a gardé en éclats. »"},{"qui":"faelis","expression":"neutre","dit":"« Ce parchemin est une copie. L'original est gravé dans les Ruines de Sel, au sud. Les elfes y sont venus il y a mille ans, pour réparer leur faute. Ils ont échoué. »"}],"effets":[{"flag":"indice-dechirure","xp":80}],"choix":[],"suite":"concorde","fin":false},"doute":{"repliques":[{"qui":"faelis","expression":"neutre","dit":"« Vous ne me croyez pas ? » Elle hausse les épaules. « Allez voir les Ruines de Sel, au sud. Les anciens y ont tout écrit. Si les tempêtes vous laissent passer. »"}],"effets":[],"choix":[],"suite":"concorde","fin":false},"concorde":{"repliques":[{"qui":"faelis","expression":"neutre","dit":"« La Concorde le sait. Elle s'en moque. Un cristal vaut plus qu'un village. » Elle range ses herbes. « Les grandes tempêtes viendront au printemps. Les Ruines de Sel ne se montrent qu'après, quand le vent a déplacé les dunes. »"},{"qui":"nadja","expression":"neutre","dit":"Nadja, qui écoutait depuis l'étal voisin, s'approche. « Une carte des Ruines, ça se trouve. Ça se paie, mais ça se trouve. » Elle hésite. « Et si l'elfe dit vrai… je travaille pour les gens qui vendent la fin du monde au détail. »"}],"effets":[{"flag":"carte-ruines","quete":{"id":"q-ch2-routes","etape":"tempete"},"journal":"Grand Bazar de 1016 : une elfe de Sylvenoire affirme que les cristaux d'éther sont des éclats du Voile."}],"choix":[],"fin":true}}},"ch2-tempete":{"id":"ch2-tempete","titre":"La tempête et les Ruines de Sel","type":"groupe","lieu":"ruines-de-sel","decor":"ruines-de-sel","debut":"debut","disponible_si":{"quete_etape":{"q-ch2-routes":"tempete"},"date_min":{"annee":1017,"mois":4,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch2-routes","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Solaire 1017. Grâce à la carte de Nadja, vous êtes à deux jours des Ruines de Sel quand le ciel devient jaune."},{"qui":"kaya","expression":"peur","dit":"Kaya renifle l'air, puis attrape la bride du premier chameau. « La grande tempête ! Il faut un abri. Maintenant ! »"},{"qui":"narrateur","expression":"neutre","dit":"Un mur de sable haut comme une montagne avale l'horizon. Vous courez. Devant vous, des colonnes blanches sortent des dunes : les Ruines."}],"effets":[],"choix":[{"texte":"Se réfugier dans les Ruines.","visible_si_bloque":false,"effets":[],"aller":"entree"}],"fin":false},"entree":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un escalier de sel cristallisé descend sous la cité morte. Le vent hurle au-dessus de vos têtes. En bas, des yeux turquoise s'allument dans le noir."}],"effets":[],"choix":[],"donjon":{"id":"ruines-de-sel","sortie":"sortie","abandon":"abandon"},"fin":false},"abandon":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Épuisés, vous remontez l'escalier de sel. Le Roi de Sel n'a pas bougé de son trône : il attendra encore mille ans."},{"qui":"narrateur","expression":"neutre","dit":"Mais vous avez vu la fresque. Les elfes en cercle, le ciel déchiré, les éclats violets qui tombent… et la phrase gravée en dessous, que Séraphine a recopiée en tremblant."},{"qui":"seraphine","expression":"neutre","dit":"« « Ce que nous avons déchiré, la terre l'a gardé en éclats. » » Elle range sa copie. « Il faut quelqu'un pour lire ça. Quelqu'un de Sylvenoire. »"}],"effets":[{"flag":"ruines-explorees","xp":100,"quete":{"id":"q-ch2-routes","etape":"revolte"},"journal":"Solaire 1017 : dans les Ruines de Sel, {groupe} découvrent une fresque elfique sur la Déchirure."}],"choix":[],"fin":true},"sortie":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Quand vous remontez, la tempête est passée. Le désert a changé de forme : les dunes ont avancé de cent pas."},{"qui":"narrateur","expression":"neutre","dit":"Dans votre sac, la tablette d'argile pèse plus lourd qu'elle ne devrait. Les mots elfiques gravés dessus brillent faiblement quand on les touche."},{"qui":"seraphine","expression":"neutre","dit":"Séraphine la retourne entre ses mains. « Il faut quelqu'un pour lire ça. Quelqu'un de Sylvenoire. » Elle sourit faiblement. « On dirait que nos routes ne font que commencer. »"}],"effets":[{"flag":"ruines-explorees","xp":200,"quete":{"id":"q-ch2-routes","etape":"revolte"},"journal":"Solaire 1017 : dans les Ruines de Sel, {groupe} trouvent une tablette elfique qui parle de la Déchirure."}],"choix":[],"fin":true}}},"ch2-revolte":{"id":"ch2-revolte","titre":"La révolte des Lunecroc","type":"groupe","lieu":"campement-lunecroc","decor":"campement-lunecroc","debut":"debut","disponible_si":{"quete_etape":{"q-ch2-routes":"revolte"},"date_min":{"annee":1017,"mois":12,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch2-routes","pnj":"sorha","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Aurore 1017. Au campement Lunecroc, les tambours de guerre résonnent depuis trois nuits."},{"qui":"sorha","expression":"neutre","dit":"L'Ancienne Sorha vous reçoit sous sa tente, appuyée sur son bâton gravé de loups. « Mon petit-fils Tavek veut attaquer les mines d'éther demain. Les mercenaires de la Concorde l'attendent. Ce sera un massacre. »"},{"qui":"kaya","expression":"tristesse","dit":"Kaya regarde ses pieds. « Tavek a toujours été le plus courageux. Et le plus têtu. Il dit que si on ne reprend pas la terre maintenant, il n'y aura plus de terre à reprendre. »"},{"qui":"tavek","expression":"neutre","dit":"Le chef de guerre entre sans s'annoncer, griffes de fer aux poings. « Les Appelés de la princesse. Vous êtes venus nous dire d'être sages ? »"},{"qui":"narrateur","expression":"neutre","dit":"Un messager couvert de poussière apporte une lettre : la Concorde promet « une prime généreuse » à quiconque aidera à protéger les mines.","si":{"flag":"hassad-redevable"}}],"effets":[],"choix":[{"texte":"Soutenir la tribu Lunecroc : vous attaquerez les mines avec Tavek.","visible_si_bloque":false,"effets":[{"flag":"soutien-lunecroc","reputation":{"ourvalis":20,"concorde":-20},"affinite":{"kaya":10,"seraphine":-3}}],"aller":"attaque"},{"texte":"Défendre les mines : la paix avec la Concorde avant tout.","visible_si_bloque":false,"effets":[{"flag":["soutien-concorde","heros:trahison-lunecroc"],"reputation":{"concorde":20,"ourvalis":-25},"affinite":{"kaya":-15}}],"aller":"defense"},{"texte":"Négocier une trêve entre Tavek et la Concorde. (Charisme, difficulté 22)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":22,"reussite":"treve","echec":"treve-ratee"},"effets":[]}],"fin":false},"attaque":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À l'aube, les guerriers lunecroc dévalent la falaise en hurlant. Vous êtes en tête. Aux mines, le capitaine Orlen Vask vous attend, cuirasse dorée au soleil."},{"qui":"vask","expression":"neutre","dit":"« Des Appelés avec des loups. La Concorde va adorer cette histoire. » Il lève son fendoir. « Feu à volonté ! »"}],"effets":[],"choix":[],"combat":{"rencontre":"revolte-vask","victoire":"mines-prises","defaite":"repli"},"fin":false},"mines-prises":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vask s'enfuit à travers le désert. Les mercenaires jettent leurs lances. Sur la plus haute galerie, Tavek plante le bâton de Sorha dans la roche violette."},{"qui":"tavek","expression":"neutre","dit":"« Cette terre est à nous. » Il se tourne vers vous, et pour la première fois, il s'incline. « Merci, Appelés. Les Lunecroc ne l'oublieront jamais. »"}],"effets":[{"flag":"mines-lunecroc","reputation":{"ourvalis":10}}],"choix":[],"suite":"fin","fin":false},"repli":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La charge se brise sur les boucliers dorés. Vous couvrez la retraite des blessés, pas à pas, jusqu'à la falaise."},{"qui":"tavek","expression":"neutre","dit":"Tavek saigne mais vit. « Vous êtes restés. Jusqu'au bout. » Il serre la main de Kaya. « On reviendra. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"defense":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous prenez position sur les galeries des mines, aux côtés des mercenaires. Quand la charge lunecroc arrive, Kaya n'est pas avec vous."},{"qui":"tavek","expression":"neutre","dit":"Tavek vous voit et s'arrête net. « Toi aussi ? » Il crache dans le sable. « Alors tu mourras avec l'or de la Concorde. »"}],"effets":[],"choix":[],"combat":{"rencontre":"revolte-tavek","victoire":"mines-tenues","defaite":"mines-perdues"},"fin":false},"mines-tenues":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tavek recule, blessé, et ordonne la retraite. La Concorde garde ses mines. Le Prévôt vous fera envoyer une bourse d'or."},{"qui":"kaya","expression":"colere","dit":"Le soir, Kaya vous attend à la porte de l'auberge. Elle ne dit rien. Elle vous regarde seulement, longtemps. Puis elle s'en va."}],"effets":[{"flag":"mines-concorde","or":200}],"choix":[],"suite":"fin","fin":false},"mines-perdues":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les Lunecroc prennent les mines. Tavek vous épargne, avec mépris. « Va dire à tes marchands ce qui arrive quand on vole la terre des loups. »"}],"effets":[{"flag":"mines-lunecroc"}],"choix":[],"suite":"fin","fin":false},"treve":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous parlez toute la nuit. À Tavek, à Sorha, puis au Prévôt Hassad, venu en personne sous un dais de soie."},{"qui":"hassad","expression":"neutre","dit":"« Un tiers des mines rendu aux Lunecroc. Et la Concorde achète leur protection, au lieu de payer des mercenaires. » Le Prévôt plisse les yeux. « Vous feriez de redoutables marchands. »"},{"qui":"sorha","expression":"joie","dit":"L'Ancienne Sorha pose sa main ridée sur votre front. « Le vent se souviendra de ton nom. »"}],"effets":[{"flag":"treve-sables","reputation":{"ourvalis":15,"concorde":5},"affinite":{"kaya":8,"seraphine":5,"nadja":3},"xp":200}],"choix":[],"suite":"fin","fin":false},"treve-ratee":{"repliques":[{"qui":"tavek","expression":"neutre","dit":"Tavek vous coupe la parole. « Des mots. Toujours des mots. » Il sort de la tente. La guerre aura lieu, avec ou sans vous."}],"effets":[],"choix":[{"texte":"Alors combattre avec les Lunecroc.","visible_si_bloque":false,"effets":[{"flag":"soutien-lunecroc","reputation":{"ourvalis":15,"concorde":-15},"affinite":{"kaya":6}}],"aller":"attaque"},{"texte":"Rester à l'écart : ce n'est pas votre guerre.","visible_si_bloque":false,"effets":[{"affinite":{"kaya":-5}}],"aller":"ecart"}],"fin":false},"ecart":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La bataille dure une journée. Les Lunecroc reprennent une galerie, en perdent deux. Au soir, chacun compte ses morts, et rien n'a changé."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"Quelques jours plus tard, une lettre royale arrive à Qarzim : le traité est signé, ou presque. Séraphine la lit, puis la jette sur la table. « Mon père veut que je rentre. Moi, je veux savoir ce que dit cette tablette. »"},{"qui":"aveline","expression":"neutre","dit":"Aveline déplie une carte. « Sylvenoire. La forêt des elfes, à l'ouest d'Aubeclaire. Personne n'y entre sans invitation. » Elle hausse les épaules. « Il faudra donc une invitation. »"},{"qui":"narrateur","expression":"neutre","dit":"La Marche des Sables a changé. Vous aussi. Derrière vous, les dunes effacent vos traces ; devant vous, une forêt qui se souvient."}],"effets":[{"xp":300,"terminer_quete":"q-ch2-routes"},{"fin_chapitre":2}],"choix":[],"fin":true}}},"sq-chacals-guilde":{"id":"sq-chacals-guilde","titre":"La Grande Mère des chacals : l'affaire","type":"groupe","lieu":"guilde-qarzim","decor":"guilde","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"matriarche-acceptee"},"repetable":false,"romance":false,"quete":"q-matriarche","pnj":"ibrek","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ibrek","expression":"neutre","dit":"Ibrek remonte ses lunettes sur son museau roux. « Sept chameaux en un mois, dans le Canyon des Chacals. Les caravaniers parlent d'une matriarche blanche, grande comme un poney. Personne ne veut le contrat : il paie mal. »"},{"qui":"kaya","expression":"neutre","dit":"Kaya ricane. « Il paie mal, mais il paie en gloire. »","si":{"flag":"kaya-recrutee"}}],"effets":[],"choix":[{"texte":"« On prend. »","visible_si_bloque":false,"effets":[{"flag":"matriarche-acceptee","quete":{"id":"q-matriarche","etape":"canyon"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"ibrek","expression":"neutre","dit":"« Le canyon est au sud-est. Prenez de l'eau, et ne faites pas confiance à l'écho. »"}],"effets":[],"choix":[],"fin":true}}},"sq-chacals-canyon":{"id":"sq-chacals-canyon","titre":"La Grande Mère des chacals : le canyon","type":"groupe","lieu":"canyon-des-chacals","decor":"canyon-des-chacals","debut":"debut","disponible_si":{"quete_etape":{"q-matriarche":"canyon"}},"repetable":false,"romance":false,"quete":"q-matriarche","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les parois rouges se resserrent. Des jappements résonnent de partout et de nulle part à la fois."}],"effets":[],"choix":[{"texte":"Avancer en silence et repérer la meute. (Agilité, difficulté 20)","visible_si_bloque":false,"test":{"carac":"AGI","difficulte":20,"reussite":"discret","echec":"repere"},"effets":[]},{"texte":"Avancer d'un pas ferme : qu'ils viennent.","visible_si_bloque":false,"effets":[],"aller":"repere"}],"fin":false},"discret":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous repérez les guetteurs avant qu'ils ne vous voient. La tanière est au fond du canyon, sous un surplomb."}],"effets":[{"xp":40,"quete":{"id":"q-matriarche","etape":"taniere"}}],"choix":[],"fin":true},"repere":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Une meute surgit des rochers !"}],"effets":[],"choix":[],"combat":{"rencontre":"chacals-dunes","victoire":"apres","defaite":"apres"},"fin":false},"apres":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les survivants fuient vers le fond du canyon, sous un surplomb. Vous savez où aller."}],"effets":[{"quete":{"id":"q-matriarche","etape":"taniere"}}],"choix":[],"fin":true}}},"sq-chacals":{"id":"sq-chacals","titre":"La Grande Mère des chacals : la tanière","type":"groupe","lieu":"canyon-des-chacals","decor":"canyon-des-chacals","debut":"debut","disponible_si":{"quete_etape":{"q-matriarche":"taniere"}},"repetable":false,"romance":false,"quete":"q-matriarche","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Sous le surplomb, une chacale énorme, au pelage presque blanc, se dresse devant ses petits. Ses yeux sont fatigués. Ses côtes saillent."},{"qui":"kaya","expression":"neutre","dit":"Kaya fronce les sourcils. « Elle a faim. Les mines ont fait fuir tout le gibier du canyon. »","si":{"flag":"kaya-recrutee"}}],"effets":[],"choix":[{"texte":"Combattre la matriarche.","visible_si_bloque":false,"effets":[],"aller":"combat"},{"texte":"Lui laisser de la viande et la chasser loin des routes. (Esprit, difficulté 22)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":22,"reussite":"paix","echec":"combat"},"effets":[]}],"fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"chacals-matriarche","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La Grande Mère tombe. Ses petits s'enfuient dans les rochers."}],"effets":[{"flag":"matriarche-tuee","quete":{"id":"q-matriarche","etape":"retour"}}],"choix":[],"fin":true},"defaite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La matriarche vous laisse au sol et emporte ses petits vers le désert profond. Elle ne reviendra pas."}],"effets":[{"quete":{"id":"q-matriarche","etape":"retour"}}],"choix":[],"fin":true},"paix":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La chacale renifle la viande, vous fixe longuement… puis s'éloigne vers le sud avec toute sa meute. Les routes seront tranquilles."},{"qui":"kaya","expression":"joie","dit":"Kaya vous regarde avec un respect nouveau. « Tu parles aux bêtes, maintenant ? »","si":{"flag":"kaya-recrutee"}}],"effets":[{"flag":"matriarche-epargnee","reputation":{"ourvalis":5},"affinite":{"kaya":5},"xp":120,"quete":{"id":"q-matriarche","etape":"retour"}}],"choix":[],"fin":true}}},"sq-chacals-retour":{"id":"sq-chacals-retour","titre":"La Grande Mère des chacals : le retour","type":"groupe","lieu":"guilde-qarzim","decor":"guilde","debut":"debut","disponible_si":{"quete_etape":{"q-matriarche":"retour"}},"repetable":false,"romance":false,"quete":"q-matriarche","pnj":"ibrek","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"ibrek","expression":"neutre","dit":"« Le canyon est sûr ? Parfait. » Ibrek trempe sa plume. « Je note : contrat rempli, avec… mention. »"}],"effets":[{"xp":250,"or":90,"points_guilde":120,"terminer_quete":"q-matriarche"}],"choix":[],"fin":true}}},"sq-puits-ziyane":{"id":"sq-puits-ziyane","titre":"Les puits asséchés : l'inquiétude de Ziyane","type":"groupe","lieu":"qarzim-oasis","decor":"qarzim-oasis","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"puits-acceptes"},"repetable":false,"romance":false,"quete":"q-puits","pnj":"ziyane","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ziyane","expression":"neutre","dit":"Mère Ziyane trempe la main dans le bassin de l'auberge. « Il baisse. Chaque semaine, un doigt de moins. Le vieux canal de l'Oasis passe par les puits du sud… et mon grand-père disait qu'il n'était jamais à sec. »"}],"effets":[],"choix":[{"texte":"« Nous irons voir. »","visible_si_bloque":false,"effets":[{"flag":"puits-acceptes","quete":{"id":"q-puits","etape":"puits"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"ziyane","expression":"neutre","dit":"« Que les puits vous soient doux. » Elle vous remplit les gourdes, gratuitement."}],"effets":[{"objet":"eau-d-oasis"}],"choix":[],"fin":true}}},"sq-puits-canal":{"id":"sq-puits-canal","titre":"Les puits asséchés : le vieux canal","type":"groupe","lieu":"puits-asseches","decor":"puits-asseches","debut":"debut","disponible_si":{"quete_etape":{"q-puits":"puits"}},"repetable":false,"romance":false,"quete":"q-puits","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les puits sont à sec. Mais dans le canal, les traces sont fraîches : des pelles, des roues de chariot… et un barrage de planches neuves qui détourne l'eau vers l'est."},{"qui":"narrateur","expression":"neutre","dit":"Vers l'est. Vers les mines d'éther."}],"effets":[{"quete":{"id":"q-puits","etape":"mines"}}],"choix":[],"fin":true}}},"sq-puits-mines":{"id":"sq-puits-mines","titre":"Les puits asséchés : l'eau des mines","type":"groupe","lieu":"mines-ether","decor":"mines-ether","debut":"debut","disponible_si":{"quete_etape":{"q-puits":"mines"}},"repetable":false,"romance":false,"quete":"q-puits","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Aux mines, l'eau du canal sert à laver le minerai violet. Des bassins entiers, troubles, gaspillés, puis rejetés dans le sable."},{"qui":"vask","expression":"neutre","dit":"Un capitaine en cuirasse dorée s'approche. « Propriété de la Concorde. Circulez. »"}],"effets":[],"choix":[{"texte":"Détruire le barrage cette nuit, en silence.","visible_si_bloque":false,"effets":[],"aller":"sabotage"},{"texte":"Exiger que l'eau soit rendue à Qarzim.","visible_si_bloque":false,"effets":[],"aller":"combat"},{"texte":"Acheter les gardes pour qu'ils « oublient » le barrage. (100 or)","si":{"or_min":100},"visible_si_bloque":false,"effets":[{"or":-100}],"aller":"achat"}],"fin":false},"sabotage":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les planches cèdent dans un grand fracas d'eau. Le canal se remplit. Au loin, des cris : on vous a vus."}],"effets":[],"choix":[],"combat":{"rencontre":"mercenaires-mines","victoire":"fini","defaite":"fini"},"fin":false},"combat":{"repliques":[{"qui":"vask","expression":"neutre","dit":"« Exiger ? » Le capitaine rit. « Gardes ! »"}],"effets":[],"choix":[],"combat":{"rencontre":"mercenaires-mines","victoire":"force","defaite":"fini"},"fin":false},"force":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les mercenaires battus démontent eux-mêmes le barrage, sous vos yeux."}],"effets":[],"choix":[],"suite":"fini","fin":false},"achat":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'or change de main. Au matin, le barrage a « mystérieusement » disparu."}],"effets":[{"reputation":{"concorde":-3}}],"choix":[],"suite":"fini","fin":false},"fini":{"repliques":[],"effets":[{"flag":"eau-rendue","reputation":{"concorde":-5},"quete":{"id":"q-puits","etape":"retour"}}],"choix":[],"fin":true}}},"sq-puits-retour":{"id":"sq-puits-retour","titre":"Les puits asséchés : le retour","type":"groupe","lieu":"qarzim-oasis","decor":"qarzim-oasis","debut":"debut","disponible_si":{"quete_etape":{"q-puits":"retour"}},"repetable":false,"romance":false,"quete":"q-puits","pnj":"ziyane","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"ziyane","expression":"joie","dit":"Le bassin déborde presque. Mère Ziyane pleure et rit en même temps. « Vous dormirez ici quand vous voudrez. Et la première nuit, c'est la maison qui offre ! »"}],"effets":[{"xp":260,"or":60,"objet":["eau-d-oasis","eau-d-oasis"],"terminer_quete":"q-puits"}],"choix":[],"fin":true}}},"sq-fantome-rumeur":{"id":"sq-fantome-rumeur","titre":"La caravane fantôme : une vieille histoire","type":"groupe","lieu":"qarzim-bazar","decor":"qarzim-bazar","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"fantome-acceptee"},"repetable":false,"romance":false,"quete":"q-caravane-fantome","pnj":"ouzram","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ouzram","expression":"neutre","dit":"Maître Ouzram cesse de polir une lame. « Il y a vingt ans, la caravane de mon frère, Belkhir, s'est perdue dans les Dunes chantantes. Certaines nuits, des caravaniers voient des lanternes là-bas… et entendent des clochettes de chameaux. »"},{"qui":"ouzram","expression":"neutre","dit":"« Je ne crois pas aux fantômes. Mais je voudrais savoir. »"}],"effets":[],"choix":[{"texte":"« Nous irons voir, Maître Ouzram. »","visible_si_bloque":false,"effets":[{"flag":"fantome-acceptee","quete":{"id":"q-caravane-fantome","etape":"dunes"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"sq-fantome-dunes":{"id":"sq-fantome-dunes","titre":"La caravane fantôme : les Dunes chantantes","type":"groupe","lieu":"dunes-chantantes","decor":"dunes-chantantes","debut":"debut","disponible_si":{"quete_etape":{"q-caravane-fantome":"dunes"}},"repetable":false,"romance":false,"quete":"q-caravane-fantome","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La nuit tombe. Les dunes chantent, une note longue et triste. Puis, au loin : des clochettes. Des lanternes. Une file de chameaux translucides avance lentement."},{"qui":"narrateur","expression":"neutre","dit":"À la tête de la caravane, un homme sans visage, couvert de sel, lève la main. Les chameaux s'arrêtent. Les chacals sortent de l'ombre."}],"effets":[],"choix":[],"combat":{"rencontre":"caravane-fantome","victoire":"belkhir","defaite":"belkhir"},"fin":false},"belkhir":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les lanternes s'éteignent une à une. Dans le sable, à la place du chef de caravane, une boîte de cuivre gravée du nom « Belkhir Telli », et une poignée de cendres."},{"qui":"narrateur","expression":"neutre","dit":"Une voix, très faible, dans le chant des dunes : « …l'oasis… ramenez-moi à l'oasis… »"}],"effets":[{"quete":{"id":"q-caravane-fantome","etape":"oasis"}}],"choix":[],"fin":true}}},"sq-fantome-oasis":{"id":"sq-fantome-oasis","titre":"La caravane fantôme : l'oasis perdue","type":"groupe","lieu":"oasis-perdue","decor":"oasis-perdue","debut":"debut","disponible_si":{"quete_etape":{"q-caravane-fantome":"oasis"}},"repetable":false,"romance":false,"quete":"q-caravane-fantome","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'oasis perdue n'est que trois palmiers morts. Vous dispersez les cendres de Belkhir au pied du plus grand."},{"qui":"narrateur","expression":"neutre","dit":"Le lendemain, vous ne l'avez pas rêvé : une pousse verte est sortie du sable. Les dunes, au loin, ne chantent plus."},{"qui":"ouzram","expression":"neutre","dit":"De retour au Bazar, Maître Ouzram écoute toute l'histoire sans un mot. Puis il vous tend une lame qu'il gardait sous son comptoir. « Elle était à mon frère. Elle sera mieux dans vos mains que dans les miennes. »"}],"effets":[{"xp":300,"objet":"crocs-jumeaux-du-canyon","terminer_quete":"q-caravane-fantome"}],"choix":[],"fin":true}}},"sq-pillards-prisonnier":{"id":"sq-pillards-prisonnier","titre":"Le repaire des pillards : le prisonnier","type":"groupe","lieu":"qarzim-porte","decor":"qarzim-porte","debut":"debut","disponible_si":{"flag":"prisonnier-pillard","pas_flag":"pillards-commences"},"repetable":false,"romance":false,"quete":"q-pillards","pnj":"nadja","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le jeune pillard de la Route des Caravanes a été retrouvé à la Porte, mendiant de l'eau.","si":{"flag":"pillard-epargne"}},{"qui":"narrateur","expression":"neutre","dit":"Le jeune pillard de la Route des Caravanes croupit dans la geôle de la Porte.","si":{"pas_flag":"pillard-epargne"}},{"qui":"nadja","expression":"neutre","dit":"Nadja s'accroupit devant lui. « Qui vous a payés pour retarder la princesse ? »"}],"effets":[],"choix":[{"texte":"Le convaincre gentiment. (Charisme, difficulté 19)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":19,"reussite":"parle","echec":"menace"},"effets":[]},{"texte":"Le menacer.","visible_si_bloque":false,"effets":[],"aller":"menace"}],"fin":false},"parle":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le garçon fond en larmes. « Un homme en soie est venu au repaire. Avec une bague violette. Il a payé en cristaux. » Il vous dit où trouver le repaire : entre deux rochers en forme de crocs, à l'est."}],"effets":[{"flag":"pillards-commences","affinite":{"nadja":2},"quete":{"id":"q-pillards","etape":"repaire"}}],"choix":[],"fin":true},"menace":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le garçon se recroqueville et parle, terrorisé. Le repaire est à l'est, entre deux rochers en forme de crocs."}],"effets":[{"flag":"pillards-commences","quete":{"id":"q-pillards","etape":"repaire"}}],"choix":[],"fin":true}}},"sq-pillards-repaire":{"id":"sq-pillards-repaire","titre":"Le repaire des pillards : l'assaut","type":"groupe","lieu":"repaire-pillards","decor":"repaire-pillards","debut":"debut","disponible_si":{"quete_etape":{"q-pillards":"repaire"}},"repetable":false,"romance":false,"quete":"q-pillards","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Des tentes rapiécées, un feu, des chameaux volés. Et des pillards qui vous attendaient."}],"effets":[],"choix":[],"combat":{"rencontre":"pillards-camp","victoire":"fouille","defaite":"fouille"},"fin":false},"fouille":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Dans la tente du chef, un coffret plein de cristaux d'éther… et un reçu, signé d'un « H. » orné d'une bague."}],"effets":[{"or":80,"objet":"cristal-ether","quete":{"id":"q-pillards","etape":"retour"}}],"choix":[],"fin":true}}},"sq-pillards-retour":{"id":"sq-pillards-retour","titre":"Le repaire des pillards : la preuve","type":"groupe","lieu":"qarzim-porte","decor":"qarzim-porte","debut":"debut","disponible_si":{"quete_etape":{"q-pillards":"retour"}},"repetable":false,"romance":false,"quete":"q-pillards","pnj":"nadja","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Nadja regarde le reçu longtemps. « Un « H. ». Ça ne prouve rien… et ça dit tout. » Elle le glisse dans son carnet. « Quelqu'un, très haut à la Concorde, ne voulait pas de ce traité. »"}],"effets":[{"flag":"recu-hassad","affinite":{"nadja":4},"xp":240,"terminer_quete":"q-pillards"}],"choix":[],"fin":true}}},"prologue-6-ans":{"id":"prologue-6-ans","titre":"Prologue — Les souvenirs d'avant (6 ans, 1000 AV)","type":"individuel","decor":"prologue-campagne","debut":"debut","disponible_si":{"pas_flag":"prologue-6","origine":"reincarne"},"repetable":false,"romance":false,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu as six ans. Ce matin, en regardant ton reflet dans une flaque, une vague d'images te submerge : des rues éclairées la nuit, des écrans, un nom qui n'est pas le tien… une autre vie, terminée trop tôt."},{"qui":"narrateur","expression":"neutre","dit":"Tu comprends, avec une clarté effrayante, que tu as déjà vécu. Et que ce monde-ci n'est pas le même."},{"qui":"narrateur","expression":"neutre","dit":"Mais d'abord : où as-tu grandi, dans cette nouvelle vie ?"}],"effets":[],"choix":[{"texte":"Dans une ferme près de la Combe-aux-Saules. Des champs de blé à perte de vue.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-6","origine_enfance":"fermier","journal":"{heros} grandit dans une ferme d'Aubeclaire."}],"aller":"ferme"},{"texte":"Dans le manoir d'une petite famille noble, entre précepteurs et étiquette.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-6","origine_enfance":"noble","journal":"{heros} grandit dans un manoir de petite noblesse."}],"aller":"manoir"},{"texte":"À l'orphelinat de l'Ordre, sous les cloches de la chapelle blanche.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-6","origine_enfance":"orphelin","journal":"{heros} grandit à l'orphelinat de l'Ordre."}],"aller":"orphelinat"},{"texte":"Dans l'arrière-boutique encombrée d'un marchand ambulant.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-6","origine_enfance":"marchand","journal":"{heros} grandit parmi les caisses d'un marchand."}],"aller":"boutique"}],"fin":false},"ferme":{"decor":"prologue-campagne","repliques":[{"qui":"narrateur","expression":"neutre","dit":"La ferme sent le foin et le pain chaud. Ta mère d'ici chante faux, ton père d'ici rit fort. Tu décides de garder ton secret… pour l'instant."}],"effets":[],"choix":[],"suite":"fin","fin":false},"manoir":{"decor":"prologue-manoir","repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les couloirs du manoir résonnent de leçons de maintien. Ton précepteur trouve que tu poses « de bien étranges questions » sur l'électricité."}],"effets":[],"choix":[],"suite":"fin","fin":false},"orphelinat":{"decor":"prologue-orphelinat","repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les sœurs sont strictes mais justes. Tu apprends vite à lire — trop vite, murmure-t-on. Une prêtresse note ton nom dans un registre."}],"effets":[],"choix":[],"suite":"fin","fin":false},"boutique":{"decor":"prologue-boutique","repliques":[{"qui":"narrateur","expression":"neutre","dit":"Entre les épices et les tapis roulés, tu apprends à compter plus vite que les adultes. Le marchand jure que tu lui porteras chance."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les souvenirs de ton ancienne vie s'estompent un peu, comme un rêve au réveil. Mais ils ne partent jamais tout à fait."}],"effets":[],"choix":[],"fin":true}}},"prologue-10-ans":{"id":"prologue-10-ans","titre":"Prologue — Le premier secret (10 ans, 1004 AV)","type":"individuel","decor":"prologue-campagne","debut":"debut","disponible_si":{"flag":"prologue-6","pas_flag":"prologue-10","origine":"reincarne"},"repetable":false,"romance":false,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu as dix ans. Une nuit d'orage, quelque chose s'éveille en toi : ton don. Il frémit sous ta peau, impatient."},{"qui":"narrateur","expression":"neutre","dit":"Un adulte entre dans la pièce au moment exact où ton don se manifeste."}],"effets":[],"choix":[{"texte":"Cacher ton don à tout prix. Personne ne doit savoir.","visible_si_bloque":false,"effets":[{"flag":["heros:prologue-10","heros:enfance-discrete"]}],"aller":"discret"},{"texte":"Lui montrer. Tu as besoin de confier ce secret à quelqu'un.","visible_si_bloque":false,"effets":[{"flag":["heros:prologue-10","heros:enfance-confiance"]}],"aller":"confiance"},{"texte":"T'en servir pour aider : le toit de la grange s'effondre sous la pluie.","visible_si_bloque":false,"effets":[{"flag":["heros:prologue-10","heros:enfance-heroique"]}],"aller":"heroique"}],"fin":false},"discret":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu inventes une excuse maladroite. L'adulte hausse les épaules. Tu apprends ce soir-là l'art de te taire — il te servira."}],"effets":[],"choix":[],"suite":"fin","fin":false},"confiance":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'adulte reste longtemps silencieux, puis te serre contre lui. « Ce sera notre secret. » Tu n'as jamais été aussi soulagé."}],"effets":[],"choix":[],"suite":"fin","fin":false},"heroique":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Ton don retient la charpente juste assez longtemps pour que les bêtes sortent. On parle de miracle au village. Toi, tu trembles toute la nuit."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Dès lors, chaque jour, tu t'entraînes en cachette. Ton corps d'enfant apprend ce que ton âme sait déjà."}],"effets":[],"choix":[],"fin":true}}},"prologue-14-ans":{"id":"prologue-14-ans","titre":"Prologue — La rencontre (14 ans, 1008 AV)","type":"individuel","decor":"prologue-campagne","debut":"debut","disponible_si":{"flag":"prologue-10","pas_flag":"prologue-14","origine":"reincarne"},"repetable":false,"romance":false,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu as quatorze ans. Cette année-là, quelqu'un entre dans ta vie et ne la quitte plus vraiment."}],"effets":[],"choix":[{"texte":"Maître Orlo, un vieux bibliothécaire bourru, qui devine ce que tu es et t'enseigne les légendes de l'Appel.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-14","contact":"mentor","journal":"{heros} devient l'élève de Maître Orlo."}],"aller":"mentor"},{"texte":"Cassian, fils de garde, fier et rapide. Il te bat à la course, tu le bats aux échecs. Rivaux pour la vie.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-14","contact":"rival","journal":"{heros} se trouve un rival : Cassian."}],"aller":"rival"},{"texte":"Pipa, rieuse et intrépide, qui t'entraîne dans toutes les bêtises du canton.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-14","contact":"ami-enfance","journal":"{heros} et Pipa deviennent inséparables."}],"aller":"amie"}],"fin":false},"mentor":{"repliques":[{"qui":"mentor","expression":"neutre","dit":"« Les Appelés d'autrefois… on les dit héros. Moi, je me demande surtout ce qu'ils ont payé pour l'être. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"rival":{"repliques":[{"qui":"rival","expression":"neutre","dit":"« La prochaine fois, je gagne. Et un jour, je serai dans la garde royale. Toi, tu feras quoi ? »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"amie":{"repliques":[{"qui":"ami-enfance","expression":"neutre","dit":"« Promets-moi qu'un jour on partira voir la mer. Promets ! »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Ce lien te suivra jusqu'à Lysmont. Peut-être même au-delà."}],"effets":[],"choix":[],"fin":true}}},"prologue-17-ans":{"id":"prologue-17-ans","titre":"Prologue — Le départ (17 ans, 1011 AV)","type":"individuel","decor":"prologue-route-lysmont","debut":"debut","disponible_si":{"flag":"prologue-14","pas_flag":"prologue-17","origine":"reincarne"},"repetable":false,"romance":false,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu as dix-sept ans. Depuis des semaines, une vibration te réveille la nuit, venue de la capitale. L'Ordre prépare quelque chose."},{"qui":"narrateur","expression":"neutre","dit":"Tu prends la route de Lysmont au lever du soleil. Avant de partir, tu reçois un dernier conseil… ou un dernier cadeau."}],"effets":[],"choix":[{"texte":"Une lettre de recommandation pour la Guilde (Guilde +10).","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-17","reputation":{"guilde":10},"atout":"lettre-guilde"}],"aller":"fin"},{"texte":"Le sceau d'une famille noble qui te doit service (Couronne +10).","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-17","reputation":{"couronne":10},"atout":"sceau-noble"}],"aller":"fin"},{"texte":"La bénédiction d'une prêtresse de l'orphelinat (Ordre +10).","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-17","reputation":{"ordre":10},"atout":"benediction"}],"aller":"fin"},{"texte":"Une bourse bien remplie, économisée sou après sou (+60 or).","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-17","or":60,"atout":"bourse"}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au loin, les tours blanches de Lysmont. Dans quelques mois, au printemps 1012, tu auras dix-huit ans… et le Temple du Seuil s'illuminera."},{"qui":"narrateur","expression":"neutre","dit":"(Fin du prologue. Ton histoire rejoint celle des autres héros au chapitre 1.)"}],"effets":[],"choix":[],"fin":true}}}},"quetes":{"q-ch2-routes":{"id":"q-ch2-routes","titre":"Chapitre 2 — Les Routes du Sud","type":"principale","chapitre":2,"niveau":8,"region":"marche-des-sables","resume":"Une mission diplomatique à Qarzim, avec la princesse Séraphine. Mais dans la cité de la Concorde, les cristaux d'éther cachent quelque chose.","etapes":[{"id":"depart","objectif":"Répondre à la convocation de la princesse Séraphine, au château de Lysmont (Germinal 1015).","scene":"ch2-depart","lieu":"chateau"},{"id":"caravane","objectif":"Escorter la caravane sur la Route des Caravanes.","scene":"ch2-caravane","lieu":"route-des-caravanes","niveau":9},{"id":"palais","objectif":"Être reçus par le Prévôt Hassad au Palais de la Concorde.","scene":"ch2-palais","lieu":"qarzim-palais","niveau":9},{"id":"complot","objectif":"Assister au banquet de la Résidence d'Aubeclaire (10 Ardent 1016).","scene":"ch2-complot","lieu":"qarzim-residence","niveau":11},{"id":"bazar","objectif":"Enquêter pendant le Grand Bazar de Qarzim (1er Brumaire 1016).","scene":"ch2-bazar","lieu":"qarzim-bazar","niveau":12},{"id":"tempete","objectif":"Traverser le désert vers les Ruines de Sel (Solaire 1017).","scene":"ch2-tempete","lieu":"ruines-de-sel","niveau":14},{"id":"revolte","objectif":"Rejoindre le campement Lunecroc : la révolte gronde (Aurore 1017).","scene":"ch2-revolte","lieu":"campement-lunecroc","niveau":14},{"id":"fin","objectif":"Chapitre terminé."}]},"q-matriarche":{"id":"q-matriarche","titre":"La Grande Mère des chacals","type":"secondaire","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Les caravanes qui passent par le canyon perdent des chameaux. Une meute énorme, menée par une matriarche presque blanche.","etapes":[{"id":"guilde","objectif":"Écouter Ibrek au Comptoir de la Guilde de Qarzim.","scene":"sq-chacals-guilde","lieu":"guilde-qarzim"},{"id":"canyon","objectif":"Descendre dans le Canyon des Chacals.","scene":"sq-chacals-canyon","lieu":"canyon-des-chacals"},{"id":"taniere","objectif":"Affronter la matriarche au fond du canyon.","scene":"sq-chacals","lieu":"canyon-des-chacals","niveau":11},{"id":"retour","objectif":"Revenir au Comptoir de la Guilde.","scene":"sq-chacals-retour","lieu":"guilde-qarzim"}]},"q-puits":{"id":"q-puits","titre":"Les puits asséchés","type":"secondaire","chapitre":2,"niveau":11,"region":"marche-des-sables","resume":"Le bassin de l'Oasis Bleue baisse chaque semaine. Mère Ziyane soupçonne quelqu'un de voler l'eau de Qarzim.","etapes":[{"id":"ziyane","objectif":"Parler à Mère Ziyane, à l'auberge de l'Oasis Bleue.","scene":"sq-puits-ziyane","lieu":"qarzim-oasis"},{"id":"puits","objectif":"Suivre l'ancien canal jusqu'aux puits asséchés.","scene":"sq-puits-canal","lieu":"puits-asseches"},{"id":"mines","objectif":"Trouver où va l'eau, du côté des mines d'éther.","scene":"sq-puits-mines","lieu":"mines-ether","niveau":12},{"id":"retour","objectif":"Rapporter la vérité à Mère Ziyane.","scene":"sq-puits-retour","lieu":"qarzim-oasis"}]},"q-caravane-fantome":{"id":"q-caravane-fantome","titre":"La caravane fantôme","type":"secondaire","chapitre":2,"niveau":12,"region":"marche-des-sables","resume":"Une caravane disparue il y a vingt ans réapparaît certaines nuits dans les Dunes chantantes.","etapes":[{"id":"rumeur","objectif":"Écouter Maître Ouzram, au Grand Bazar.","scene":"sq-fantome-rumeur","lieu":"qarzim-bazar"},{"id":"dunes","objectif":"Attendre la nuit dans les Dunes chantantes.","scene":"sq-fantome-dunes","lieu":"dunes-chantantes","niveau":13},{"id":"oasis","objectif":"Rapporter les cendres du marchand à l'Oasis perdue.","scene":"sq-fantome-oasis","lieu":"oasis-perdue"}]},"q-pillards":{"id":"q-pillards","titre":"Le repaire des pillards","type":"secondaire","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Les pillards qui ont attaqué votre caravane ont un repaire. Et quelqu'un, à Qarzim, les paie.","etapes":[{"id":"indice","objectif":"Faire parler le prisonnier, à la Porte des Caravanes.","scene":"sq-pillards-prisonnier","lieu":"qarzim-porte"},{"id":"repaire","objectif":"Attaquer le repaire des pillards.","scene":"sq-pillards-repaire","lieu":"repaire-pillards","niveau":11},{"id":"retour","objectif":"Montrer les preuves à Nadja, à la Porte des Caravanes.","scene":"sq-pillards-retour","lieu":"qarzim-porte"}]},"q-kaya":{"id":"q-kaya","titre":"Le Hurlement des Ancêtres","type":"compagnon","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Kaya revient chez les siens, chassés de leurs terres. Elle veut devenir rang S pour leur rendre leur fierté.","etapes":[{"id":"tribu","objectif":"Accompagner Kaya au campement Lunecroc (palier « Proche »).","scene":"ky-hurlement","lieu":"campement-lunecroc"},{"id":"terres","objectif":"Aider Kaya à reprendre une part des terres de sa tribu (chapitre 4)."},{"id":"rang-s","objectif":"Passer l'épreuve du rang S avec Kaya (chapitre 5)."}]},"q-nadja":{"id":"q-nadja","titre":"Le Grand Livre rouge","type":"compagnon","chapitre":2,"niveau":11,"region":"marche-des-sables","resume":"La dette de Nadja est écrite dans un livre de comptes secret de la Concorde. Ce livre dit aussi qui achète les cristaux.","etapes":[{"id":"livre","objectif":"Aider Nadja à copier le Grand Livre rouge (palier « Proche »).","scene":"nd-livre","lieu":"qarzim-palais"},{"id":"acheteurs","objectif":"Suivre la piste des acheteurs de cristaux (chapitre 4)."},{"id":"liberte","objectif":"Libérer Nadja de sa dette (chapitre 5)."}]},"q-seraphine":{"id":"q-seraphine","titre":"La Couronne et le Masque","type":"compagnon","chapitre":2,"niveau":11,"region":"marche-des-sables","resume":"Séraphine n'a jamais cru à la mort de son frère Aldric. À Qarzim, quelqu'un a vu un homme portant son anneau.","etapes":[{"id":"anneau","objectif":"Suivre la piste de l'anneau d'Aldric avec Séraphine (palier « Proche »).","scene":"sr-anneau","lieu":"qarzim-bazar"},{"id":"rumeurs","objectif":"Trouver où l'anneau a été vendu (chapitre 4)."},{"id":"aldric","objectif":"Retrouver Aldric (chapitre 5)."}]},"q-classe-lame-runique":{"id":"q-classe-lame-runique","titre":"Classe — La rune perdue","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Une rune gravée sur une colonne des Ruines de Sel ne ressemble à aucune autre.","etapes":[{"id":"etape1","objectif":"Déchiffrer la rune de la colonne brisée (Lame runique).","scene":"cl-lame-runique-1","lieu":"qarzim-bazar"},{"id":"etape2","objectif":"Forger la rune à Karak-Dûm (chapitre 4)."},{"id":"etape3","objectif":"Graver la rune des Mille Sceaux (chapitre 5)."}]},"q-classe-arcaniste":{"id":"q-classe-arcaniste","titre":"Classe — Le feu du désert","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Un ermite du désert dit savoir dompter la foudre des tempêtes de sable.","etapes":[{"id":"etape1","objectif":"Trouver l'ermite des dunes (Arcaniste).","scene":"cl-arcaniste-1","lieu":"qarzim-porte"},{"id":"etape2","objectif":"Capturer le feu d'un volcan de Grisfer (chapitre 4)."},{"id":"etape3","objectif":"Faire converger les quatre éléments (chapitre 5)."}]},"q-classe-invocateur":{"id":"q-classe-invocateur","titre":"Classe — Le pacte des bêtes","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Les esprits des bêtes du désert répondent mal à l'appel. Il faut leur parler, pas leur ordonner.","etapes":[{"id":"etape1","objectif":"Parler à l'esprit du grand fennec (Invocateur).","scene":"cl-invocateur-1","lieu":"campement-lunecroc"},{"id":"etape2","objectif":"Gagner la confiance d'un esprit-dragon (chapitre 4)."},{"id":"etape3","objectif":"Ouvrir la Porte du Bestiaire (chapitre 5)."}]},"q-classe-ombre":{"id":"q-classe-ombre","titre":"Classe — La Main et l'Ombre","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"La Main de Sable recrute. Pour une Ombre, c'est une occasion… ou un piège.","etapes":[{"id":"etape1","objectif":"Répondre à l'invitation sur les toits de Qarzim (Ombre).","scene":"cl-ombre-1","lieu":"qarzim-porte"},{"id":"etape2","objectif":"Retrouver le maître qui a formé Kezir (chapitre 4)."},{"id":"etape3","objectif":"Apprendre les Mille Coupures (chapitre 5)."}]},"q-classe-gardien":{"id":"q-classe-gardien","titre":"Classe — Le serment du bouclier","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Un vieux paladin de l'Ordre vit en ermite près des puits. Il garde un bouclier sans blason.","etapes":[{"id":"etape1","objectif":"Trouver le paladin des puits (Gardien).","scene":"cl-gardien-1","lieu":"qarzim-oasis"},{"id":"etape2","objectif":"Tenir la passe des Mille Marches (chapitre 4)."},{"id":"etape3","objectif":"Prêter le serment du Bastion éternel (chapitre 5)."}