ssage.","resultat":"Les toiles se consument en crépitant. Le fond du boyau s'agite.","effets":[]},{"texte":"Avancer en les écartant à la lame.","resultat":"Vous progressez lentement. Des fils vibrent sous vos pas.","effets":[]}]},{"lieu":"crypte-nid","objectif":"Détruire le nid.","texte":"Huit yeux, puis seize, puis davantage.","choix":[],"combat":"crypte-araignees"},{"lieu":"guilde","objectif":"Revenir à la Guilde toucher la récompense.","texte":"Rowena fronce le nez. « Lavez-vous. Ensuite, la prime. »","bouton":"Toucher la récompense","choix":[]}],"rencontre":"crypte-araignees","duree_jours":3,"recompenses":{"or":80,"xp":110,"points_guilde":45,"objets":[]}},"c-egouts":{"id":"c-egouts","titre":"Rats dans les égouts","description":"Les égouts sous la place de Lysmont grouillent de rats géants et de gelées.","rang_min":"F","niveau":1,"etapes":[{"lieu":"egouts","objectif":"Descendre dans les égouts de Lysmont.","texte":"Deux galeries partent de l'escalier. À gauche, des couinements. À droite, un clapotis gluant.","choix":[{"texte":"Prendre à gauche.","resultat":"Des dizaines de petits yeux rouges reculent devant votre torche… puis s'arrêtent.","effets":[]},{"texte":"Prendre à droite.","resultat":"Une masse translucide glisse le long du mur, et les rats la suivent.","effets":[]}]},{"lieu":"egouts","objectif":"Nettoyer la galerie.","texte":"Ils sont plus gros que des chats. Et ils ont faim.","choix":[],"combat":"egouts-lysmont"},{"lieu":"guilde","objectif":"Revenir à la Guilde toucher la récompense.","texte":"« Les égouts ? Déjà ? » Rowena a presque l'air impressionnée.","bouton":"Toucher la récompense","choix":[]}],"rencontre":"egouts-lysmont","duree_jours":2,"recompenses":{"or":25,"xp":40,"points_guilde":20,"objets":[]}},"c-sangliers":{"id":"c-sangliers","titre":"Les sangliers des champs","description":"Deux sangliers ravagent les champs de blé au nord de la capitale.","rang_min":"F","niveau":3,"etapes":[{"lieu":"champs-du-nord","objectif":"Aller aux champs de blé du 